select r.id, v.* from r, (values
  ('딥 초코 체리 프라페', '음료', '꾸덕하고 진한 초콜릿에 상큼한 체리잼 스프레드를 더해 섞으면 섞을수록 맛있어지는 달콤함이 매력적인 초코 프라페 * 체리 씨를 제거하였으나, 드물게 씨 조각이 남아 있을 수 있으니 섭취 시 주의하시기 바랍니다.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261021185329_1792576409658_TSL3J4XMIy.png', null::integer, 0::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('쫀득 모찌 밀크티', '음료', '고소한 율무를 더한 우롱 루이보스티 베이스에 쪼온득 말랑한 미니 모찌펄이 가득! 함께 저어서 쏙쏙 먹으면 더욱 맛있게 즐길 수 있는 밀크티', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261021185621_1792576581002_NyaJL6AVnt.png', null::integer, 1::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('매실 모과차', '음료', '돼지파티 후엔 매실이 딱! 향긋한 매실에 은은한 모과청을 더해 식후에도 부담없이 즐길 수 있는 깔끔 담백한 매실 티플레저', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261021185422_1792576462096_Ju7aC8KXEI.png', null::integer, 2::integer, array['sulfites']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('나 혼자만 드랍 UP! 은랑 큐브 레몬에이드', '음료', '메가MGC커피 시스템을 해킹 해버린 은랑 LV.999가 블루베리 레몬에이드에 에테르 큐브를 잔뜩 드랍해놨다! 새콤달콤 시원한 에이드 곳곳에 숨어있는 큐브(나타드코코)를 하나씩 공략하는 재미가 있는 붕괴: 스타레일 한정판 음료', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261008180940_1791450580164_7pt7Ed_UTa.png', null::integer, 3::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('음, 괜찮은 휴식이군 블레이드 초코크림커피', '음료', '아무리 오래 무뎌진 마음도, 이 한 잔의 다정함은 이기지 못해 깔끔한 아메리카노 위로 진한 초코 크림이 듬뿍- 블레이드조차 인정한 달콤쌉쌀한 붕괴: 스타레일 한정판 음료', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261008180742_1791450462501_fdbGBH46Jw.png', null::integer, 4::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('하우스밀크 라떼', '음료', '메가MGC커피만의 하우스밀크로 고소하고 부드러운 맛과 은은한 단맛은 더하고 깊은 풍미의 에스프레소 샷을 블렌딩해 더욱 조화로운 밸런스를 완성한 카페라떼', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260902203101_1788348661533_weMnhAbV2Q.jpg', null::integer, 5::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('무카페인 오르조라떼', '음료', '이탈리아산 크라스탄 오르조와 고소하고 부드러운 우유가 만나 카페라떼 그대로의 깊은 풍미를 부담없이 무카페인으로 즐길 수 있는 라떼', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261028231148_1793196708947_Ohmw9SD0GT.jpg', null::integer, 6::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('저당 골든애플 블랙티', '음료', '저당으로 부담없는 달콤상큼한 사과와 깊고 깔끔한 블랙티의 조화로 더욱 풍부하고 산뜻하게 즐길 수 있는 티플레져 *대체당(알룰로스)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260916234952_1789570192916_xCpTUY41pJ.jpg', null::integer, 7::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('ARIH 듀얼바이오틱 소다 레드 루비 갈로어', '음료', '4가지 식물성 바이오틱스와 5가지 포스트바이오틱스를 더한 저당·저칼로리 듀얼 바이오틱 소다 자몽 맛 *대체당(알룰로스 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260604210115_1780574475408_4CvZdY5F9E.png', null::integer, 8::integer, array['milk', 'soy', 'peach']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 듀얼바이오틱 소다 포지티브 오렌지', '음료', '4가지 식물성 바이오틱스와 5가지 포스트바이오틱스를 더한 저당·저칼로리 듀얼 바이오틱 소다 오렌지 향 *대체당(알룰로스 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260604210526_1780574726295_ldS4q_W8ek.png', null::integer, 9::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 듀얼바이오틱 소다 클리어레몬', '음료', '4가지 식물성 바이오틱스와 5가지 포스트바이오틱스를 더한 저당·저칼로리 듀얼 바이오틱 소다 레몬 향 *대체당(알룰로스 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260605000738_1780585658684_eFPxfdhaWp.png', null::integer, 10::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 듀얼바이오틱 소다 피치망고 호라이즌', '음료', '4가지 식물성 바이오틱스와 5가지 포스트바이오틱스를 더한 저당·저칼로리 듀얼 바이오틱 소다 복숭아와 달콤한 망고 맛 *대체당(알룰로스 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260604210410_1780574650849_ge2Rbb2mCd.png', null::integer, 11::integer, array['milk', 'soy', 'peach']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 포스트바이오틱 에너지 드링크 레몬크레스트', '음료', '자연에서 온 카페인과 포스트바이오틱스를 더한 당류 ZERO, 칼로리 ZERO 에너지 드링크 시트러스 *대체당을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260604205718_1780574238227_vre8909Ms_.png', null::integer, 12::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 포스트바이오틱 에너지 드링크 오렌지아워', '음료', '자연에서 온 카페인과 포스트바이오틱스를 더한 당류 ZERO, 칼로리 ZERO 에너지 드링크 오렌지 *대체당을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260604205615_1780574175202_LHw12vYQ6H.png', null::integer, 13::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('ARIH 포스트바이오틱 에너지 드링크 트로피칼웨이브', '음료', '자연에서 온 카페인과 포스트바이오틱스를 더한 당류 ZERO, 칼로리 ZERO 에너지 드링크 리치 *대체당을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260605103322_1780623202696_F8N06YR5cD.png', null::integer, 14::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('저당 꿀배 XO야쿠르트', '음료', '저당으로 부담은 덜고, 새콤달콤한 맛은 더 풍부하게! 꿀처럼 달콤한 배의 시원하고 깨끗한 단맛에 설탕·당류·지방 3 ZERO 야쿠르트 XO 2병이 들어간 리프레쉬 한 잔 *대체당(알룰로스, 에리스리톨 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260401192153_1775038913170_2UFRSEFHv0.png', null::integer, 15::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('딸기라떼', '음료', '딸기과육이 풍부히 느껴지는 스테디 셀러 산뜻하고 달콤한 딸기가 가득해 부드러운 우유와 어우러져 더욱 기분 좋게 즐기는 아이스 라떼', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20250116001724_1736954244791_8qDsY0gj14.jpg', null::integer, 16::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('밀크쉐이크', '음료', '우유 그대로의 부드러움에 달콤함을 더해 꾸덕하고 진~한 풍미를 느낄 수 있는 겨울시즌 한정 밀크쉐이크', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20251210220621_1765371981583_lnOltIAEKR.png', null::integer, 17::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('유자생강차', '음료', '상큼달콤한 유자청과 은은하게 매콤한 생강의 풍미를 조화롭게 담아낸 겨울 한정 과일 티', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20251106022624_1762363584516_gmIV9uXczk.png', null::integer, 18::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('초코젤라또 말차라떼', '음료', '진하고 꾸덕한 초코 젤라또를 제주산 고품질 말차, 쌉싸름한 블렌딩 커피와 함께 즐기는 말차 에스프레소 라떼 *[원료 변경에 따른 전환 기간으로, 매장에 따라 기존 원료 또는 변경 원료가 사용될 수 있습니다. 변경 원료 사용 시 영양정보는 아래 내용을 참고해 주세요.] 알레르기 유발 성분 - 우유, 대두 칼로리 332.3kcal, 탄수화물 56.4g, 당류 52.3g, 단백질 7.1g, 지방 8.7g, 포화지방 4.1g, 트랜스지방 0g, 나트륨 105.2mg, 콜레스테롤 22.5mg, 카페인 213.5mg 고카페인 함유 : 해당 제품은 다량의 카페인을 함유하고 있어 어린이, 임산부, 카페인에 민감하신 분들은 유의하시기 바랍니다.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20251210155814_1765349894904_ps9wkFJ_kA.jpg', null::integer, 19::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('(HOT)헛개리카노', '음료', '국내산 헛개수와 메가MGC커피만의 아메리카노를 더해 고소한 맛이 조화로운 블렌딩 커피', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20250320000737_1742396857693_ngpZI3EbLM.jpg', null::integer, 20::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
