  ('디카페인 헤이즐넛 아메리카노', '음료', '디카페인 아메리카노에 헤이즐넛의 풍성한 향과 달콤함을 담아 향긋하고 부드럽게 즐기는 커피.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105046_1717984246492_KeavFH2VTO.jpg', null::integer, 51::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('디카페인 바닐라 아메리카노', '음료', '디카페인 아메리카노에 바닐라의 부드러운 향과 달콤함을 조화롭게 담아낸 커피.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610104650_1717984010944__Ck8jyuaDL.jpg', null::integer, 52::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('디카페인 카페라떼', '음료', '디카페인 에스프레소와 부드러운 우유가 어우러져 고소한 풍미를 완성한 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105117_1717984277710_7BjonXSBFE.jpg', null::integer, 53::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 카푸치노', '음료', '디카페인 에스프레소와 부드러운 우유가 어우러져 고소한 풍미를 완성한 카푸치노.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105545_1717984545629_CaGhOpvAnm.jpg', null::integer, 54::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 바닐라라떼', '음료', '디카페인으로 즐기는 바닐라의 짙은 향과 풍부한 폼 밀크의 조화가 인상적인 달콤한 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610104630_1717983990934_v3HPYN93uK.jpg', null::integer, 55::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 헤이즐넛 라떼', '음료', '부드러운 카페라떼에 헤이즐넛의 풍부한 향과 달콤함을 담아 향긋하게 즐길 수 있는 디카페인 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105007_1717984207073_HqCto2mw3y.jpg', null::integer, 56::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 카라멜마끼아또', '음료', '폼 밀크 속에 진한 디카페인 에스프레소와 달콤한 카라멜을 가미해 부드럽게 즐기는 커피', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105238_1717984358779_MvgzcNlZdI.jpg', null::integer, 57::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 연유라떼', '음료', '디카페인 에스프레소 샷, 부드러운 우유 그리고 달콤한 연유가 조화롭게 어우러진 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105224_1717984344775_9iKsKownRh.jpg', null::integer, 58::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 카페모카', '음료', '초코를 만나 풍부해진 디카페인 에스프레소와 고소한 우유, 부드러운 휘핑크림까지 더해 달콤하게 즐기는 커피.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105145_1717984305671_2_yE7sXma9.jpg', null::integer, 59::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('디카페인 메가리카노', '음료', '메가MGC커피 디카페인 아메리카노를 ''960ml'' 더 크고 가볍게 즐길 수 있는 대용량 커피', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610115001_1717987801368_av938eflM8.jpg', null::integer, 60::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('딸기쿠키프라페', '음료', '부드러운 바닐라와 달달한 딸기, 바삭한 오레오 쿠키가 달콤한 하모니를 선물하는 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132048_1717993248890_NW1QEUmFtQ.jpg', null::integer, 61::integer, array['milk', 'wheat', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('콜드브루디카페인', '음료', '카페인을 줄였지만, 원두 본연의 향미를 풍부하게 살려 맛을 잡은 디카페인 콜드브루.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132920_1717993760751_69WHioWjnb.jpg', null::integer, 62::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('콜드브루디카페인라떼', '음료', '우유와 만나 부드럽고 고소한 풍미가 더해진 콜드브루 디카페인 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132902_1717993742550_EBciHOxu2w.jpg', null::integer, 63::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('에스프레소', '음료', '메가MGC커피 원두의 향미를 온전히 즐길 수 있는 에스프레소', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105357_1717984437294_AduuhU3VyW.jpg', null::integer, 64::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('에스프레소 도피오', '음료', '더블샷으로 더욱 진하게 즐길 수 있는 에스프레소', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105413_1717984453131_1es5v0RxH2.jpg', null::integer, 65::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('쿠키프라페', '음료', '바삭하고 달콤한 오레오와 고소한 우유, 부드러운 바닐라향의 조화를 느낄 수 있는 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610115315_1717987995816_oiPZ2u5dJr.jpg', null::integer, 66::integer, array['milk', 'wheat', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('고구마라떼', '음료', '달콤하고 고소한 고구마와 부드러운 우유가 만나 누구나 즐기기 좋은 든든한 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610104240_1717983760778_agCooQEUb4.jpg', null::integer, 67::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('곡물라떼', '음료', '우유에 곡물을 더해 고소하고 든든하게 즐기는 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610104323_1717983803197_Dpwa_RK4_F.jpg', null::integer, 68::integer, array['milk', 'wheat', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('토피넛라떼', '음료', '은은하게 퍼지는 카라멜의 달달한 향기와 견과의 고소함을 한입에 즐길 수 있는 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105954_1717984794244_2JeEMNYiCL.jpg', null::integer, 69::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('오레오초코라떼', '음료', '진한 초코와 리얼 오레오를 블렌딩해 씹는 맛을 더한 달콤한 아이스 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132638_1717993598875_AQ4q6GUaJD.jpg', null::integer, 70::integer, array['milk', 'wheat', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('흑당버블밀크티라떼', '음료', '타바론 얼그레이 홍차의 깊은 맛을 살린 밀크티 라떼에 진한 흑당과 흑당 버블의 달콤함을 채운 음료.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610112956_1717986596859_dSAYDVVaV2.jpg', null::integer, 71::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('핫초코', '음료', '부드러운 우유에 진한 초코소스가 어우러져 달콤하게 입맛을 깨우는 초콜릿 음료.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610110045_1717984845295_sGoEnUlQpO.jpg', null::integer, 72::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('녹차라떼', '음료', '향긋한 녹차에 우유를 더해 입 안에 부드러운 푸릇함을 선물하는 라떼. *[원료 변경에 따른 전환 기간으로, 매장에 따라 기존 원료 또는 변경 원료가 사용될 수 있습니다. 변경 원료 사용 시 영양정보는 아래 내용을 참고해 주세요.] 알레르기 유발 성분 - 우유 칼로리 288.1kcal, 탄수화물 42.3g, 당류 42.1g, 단백질 8.5g, 지방 9.3g, 포화지방 5.8g, 트랜스지방 0g, 나트륨 125.7mg, 콜레스테롤 37.5mg, 카페인 82.9mg', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610104456_1717983896154_TxgXQHRHiM.jpg', null::integer, 73::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('로얄밀크티라떼', '음료', '우유와 은은한 홍차가 어우러져 부드럽고 향긋한 한 모금을 완성한 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105616_1717984576627_IStTaWZY3_.jpg', null::integer, 74::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('흑당라떼', '음료', '모리셔스의 진한 흑당과 부드러운 우유가 달콤하게 조화를 이루는 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610113159_1717986719673_UjpcQYhtmh.jpg', null::integer, 75::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
