  ('카푸치노', '음료', '에스프레소 위에 올려진 우유 거품, 그리고 시나몬 파우더로 완성한 조화로운 맛의 커피.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105852_1717984732750_WEt0KXVcnQ.jpg', null::integer, 87::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('콜드브루라떼', '음료', '콜드브루에 고소한 우유를 섞어, 깔끔함과 부드러움을 잡은 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105923_1717984763591_cKSGllWUzt.jpg', null::integer, 88::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('콜드브루오리지널', '음료', '차가운 물에 장시간 우려내 깔끔한 목넘김을 느낄 수 있는 콜드브루.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105941_1717984781078_rdCUXhwycL.jpg', null::integer, 89::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('헤이즐넛라떼', '음료', '부드러운 카페라떼에 헤이즐넛의 풍부한 향과 달콤함을 담아 향긋하게 즐길 수 있는 라떼.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610110117_1717984877061_sLiVRNPq6J.jpg', null::integer, 90::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
