  ('녹차프라페', '음료', '향긋한 녹차 위에 우유와 휘핑크림을 더해 더 부드럽게 즐길 수 있는 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260318150847_1773814127229_oIDmdAQwND.png', null::integer, 93::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('딸기요거트스무디', '음료', '요거트의 상큼함과 딸기의 상큼함을 상냥하게 어우른 상큼 스무디.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132117_1717993277823_KRGDVA4aeJ.jpg', null::integer, 94::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
