  ('리얼초코프라페', '음료', '진한 초코소스와 부드러운 바닐라향의 만남으로 질리지 않는 달콤함을 완성한 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132157_1717993317456_RCHCZKkudt.jpg', null::integer, 96::integer, array['milk', 'soy', 'wheat']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('망고요거트스무디', '음료', '열대과일 망고의 진한 단 맛과 산뜻한 요거트의 하모니가 인상적인 스무디.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132210_1717993330781_04rKlgIKk6.jpg', null::integer, 97::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('민트프라페', '음료', '상쾌한 민트에 달콤하게 씹는 재미를 더한 초콜릿칩의 즐거운 하모니가 매력적인 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610115353_1717988033471_n8WL4rST4C.jpg', null::integer, 98::integer, array['milk', 'soy', 'wheat']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
