  ('초코허니퐁크러쉬', '음료', '리얼 벌꿀이 들어가 더 달콤한 퍼프허니 시리얼과 부드럽게 달달한 초코가 함께 만드는 즐거운 맛의 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132651_1717993611266_QFRonrkBzf.jpg', null::integer, 100::integer, array['milk', 'wheat', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('커피프라페', '음료', '바삭한 쿠키와 부드러운 바닐라에 향긋한 에스프레소를 섞어 만든 힐링 프라페.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132804_1717993684465__jH6f5a2VM.jpg', null::integer, 101::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('플레인요거트스무디', '음료', '더 시원하게 요거트의 새콤달콤한 맛을 오롯이 만끽할 수 있는 스무디.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240612101151_1718154711606_iC5h64zrID.jpg', null::integer, 102::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
