  ('라임모히또', '음료', '상큼한 라임과 달콤한 향기의 애플민트가 어우러져 상쾌함을 한잔에 가득 채운 무알콜 모히또 음료.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132145_1717993305587_JyUa7vPj3s.jpg', null::integer, 104::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
