  ('페퍼민트', '음료', '멘톨향의 묵직한 청량감, 상쾌한 맛과 향이 인상적인 허브티.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610110026_1717984826888_gfP6LsxEV3.jpg', null::integer, 115::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('복숭아아이스티', '음료', '깊은 맛의 홍차와 달콤한 복숭아의 은은한 향이 어우러진 시원한 여름철 인기 음료.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610132446_1717993486995_hvfli27vPn.jpg', null::integer, 116::integer, array['peach', 'sulfites']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('유자차', '음료', '비타민이 가득 든 상큼달콤한 유자를 듬뿍 넣어 향긋한 즐거움을 전하는 과일티.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105725_1717984645282_YfXeYsJzVV.jpg', null::integer, 117::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('레몬차', '음료', '상큼한 레몬의 맛과 향을 오롯이 살린 비타민C 가득한 과일티.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105600_1717984560889__UGBqFya7F.jpg', null::integer, 118::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('자몽차', '음료', '달콤쌉싸름한 자몽의 조화로운 맛을 한 잔 가득 느낄 수 있는 과일티.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610105747_1717984667913_eDh3AjWACb.jpg', null::integer, 119::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('허니자몽블랙티', '음료', '달콤한 꿀청에 재운 자몽에 홍차의 부드러움을 어우른 상큼한 과일티.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20240610110100_1717984860663_v7Af5f77sc.jpg', null::integer, 120::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
