  ('엠지씨네 마라 떡볶이', '푸드', '매콤 얼얼한 마라 소스를 그대로! 쫀득한 떡과 빠질 수 없는 푸주, 유부, 소시지 등 마라탕 속 인기 재료를 듬뿍 담아 먹을수록 매력에 빠져드는 마라 컵 떡볶이', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261021185813_1792576693475_CPlWEhkpD0.png', null::integer, 123::integer, array['milk', 'peanut', 'soy', 'wheat', 'pork', 'chicken', 'beef']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('햄치즈에그 샌드위치', '푸드', '햄과 치즈, 계란프라이에 신선한 양상추와 토마토를 풍성하게 더한 든든한 햄치즈에그 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019233209_1792420329590_Du4b9duw4F.png', null::integer, 124::integer, array['egg', 'milk', 'soy', 'wheat', 'pork', 'tomato', 'sulfites', 'beef', 'shellfish']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('에그마요 샌드위치', '푸드', '부드러운 에그마요를 듬뿍 담아 촉촉하고 고소하게 즐기는 에그마요 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019233407_1792420447157_0Z4AiRHXeh.png', null::integer, 125::integer, array['egg', 'milk', 'soy', 'wheat']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('크래미마요 샌드위치', '푸드', '쫄깃하고 촉촉한 크래미마요에 햄과 치즈, 신선한 채소까지 알차게 담아 부드럽고 든든하게 즐기는 크래미마요 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019233829_1792420709705_z_HwQ1qU8x.png', null::integer, 126::integer, array['egg', 'milk', 'soy', 'wheat', 'crab', 'pork', 'tomato', 'sulfites', 'beef']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('모짜렐라 바질치킨 샌드위치', '푸드', '향긋한 바질페스토와 담백한 닭가슴살, 쫄깃한 모짜렐라에 신선한 채소를 더한 모짜렐라 바질치킨 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019234146_1792420906672_bVnHS670C9.png', null::integer, 127::integer, array['egg', 'milk', 'soy', 'wheat', 'tomato', 'chicken']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('불고기 에그 샌드위치', '푸드', '감칠맛 가득한 불고기와 고소한 계란, 치즈와 신선한 채소를 푸짐하게 담은 든든한 K-불고기 에그 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019234346_1792421026693_K_d6fHyqxa.png', null::integer, 128::integer, array['egg', 'milk', 'soy', 'wheat', 'pork', 'beef', 'shellfish']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('스파이시 치킨텐더 샌드위치', '푸드', '매콤한 치킨텐더에 특별한 스리라차 소스와 치즈, 신선한 채소를 더한 스파이시 치킨텐더 샌드위치', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20261019234547_1792421147743_xqbvN7b7Nx.png', null::integer, 129::integer, array['egg', 'milk', 'soy', 'wheat', 'tomato', 'chicken', 'beef']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('중식마녀 마라크림 새우토스트', '푸드', '수리수리 중마수리~ 바삭한 식빵과 고소한 새우 패티에 매콤달콤 부드러운 마라크림 소스를 더해 풍성한 맛과 식감을 담아낸 중식마녀 특제 토스트', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260826193109_1787740269466_ydyECbIq8A.jpg', null::integer, 130::integer, array['wheat', 'egg', 'milk', 'soy', 'shrimp', 'beef', 'shellfish']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('메가MGC커피 자일리톨 커피 캔디', '푸드', '향긋하고 진-한 커피향에 상쾌한 자일리톨의 마무리를 더해, 입이 텁텁해질 때에나 집중이 필요할 때! 언제든 부담 없이 즐길 수 있는 엠지씨네 zero sugar 데일리 커피 캔디 *대체당(당알코올 등)을 과도하게 섭취 시 개인에 따라 복통 및 설사 등을 유발 할 수 있으니 주의하세요.', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260818100457_1787015097342_UJvIoB_s5q.png', null::integer, 131::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('버터가 쫀득해떡', '푸드', '고소달달한 버터 풍미와 쫀득한 식감을 더해 가볍게 즐기기 좋은 한입 디저트', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20260407215938_1775566778053_U6yDWuVmpF.jpg', null::integer, 132::integer, array['wheat', 'milk', 'soy', 'egg']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('메가베리 아사이볼', '푸드', '상큼달콤 아사이볼 속에 세가지의 달콤한 베리와 건강한 그래놀라가 더해져 시원 달달하게 즐길 수 있는 디저트', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20250110194433_1736505873493_vTcz8ed6Rq.jpg', null::integer, 133::integer, array['wheat']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('딥치즈 불고기 베이크', '푸드', '바삭한 치즈가 올려진 빵 속 달콤 짭쪼롬한 불고기에 부드러운 체다치즈가 더해져 한 입 베어물면 입안 가득 풍미가 퍼지는 겨울시즌 한정 디저트', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20251210221138_1765372298850_VHrPG40Uqa.png', null::integer, 134::integer, array['wheat', 'milk', 'soy', 'pork', 'egg']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
  ('요거젤라또 초코베리믹스', '푸드', '초코쉘을 입힌 요거트 젤라또에 세가지 달콤상큼 베리와 초코링, 고소한 그래놀라를 더한, 시원달달 요거볼', 'https://img.mega-mgccoffee.com/megahp/manager/upload/menu/20250902171808_1756801088394_2yZlbc_jH9.jpg', null::integer, 135::integer, array['wheat', 'soy', 'milk']::text[], array[]::text[], array[]::text[], 'Mega MGC Coffee menu (mega-mgccoffee.com)', null::text, array[]::text[]),
