  ('복숭아 소다', '음료', '아이스크림을 얹어 더 시원한 톡톡 튀는 복숭아 소다', 'https://paikdabang.com/wp-content/uploads/2026/07/%EB%B3%B5%EC%88%AD%EC%95%84-%EC%86%8C%EB%8B%A4-450x588.png', null::integer, 135::integer, array['peach', 'milk', 'soy']::text[], array[]::text[], array[]::text[], 'Paik''s Coffee menu (paikdabang.com)', null::text, array[]::text[]),
  ('자두스무디', '음료', '새콤달콤한 자두의 맛이 잘 살아있는 자두스무디', 'https://paikdabang.com/wp-content/uploads/2026/07/%EC%9E%90%EB%91%90%EC%8A%A4%EB%AC%B4%EB%94%94-450x588.png', null::integer, 136::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Paik''s Coffee menu (paikdabang.com)', null::text, array[]::text[]),
  ('애플스무디', '음료', '시원하고 청량한 청사과맛이 잘 살아있는 애플스무디', 'https://paikdabang.com/wp-content/uploads/2026/07/%EC%95%A0%ED%94%8C%EC%8A%A4%EB%AC%B4%EB%94%94-450x588.png', null::integer, 137::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Paik''s Coffee menu (paikdabang.com)', null::text, array[]::text[]),
  ('수박망고아이스티', '음료', '시원한 수박주스에 복숭아아이스티와 망고를 더해, 풍성한 과일 맛이 느껴지는 수박망고아이스티 *카페인 함유)어린이/임산부 및 카페인에 민감한 사람은 섭취에 주의(1잔당 약 10.9mg)', 'https://paikdabang.com/wp-content/uploads/2026/07/%EC%88%98%EB%B0%95%EB%A7%9D%EA%B3%A0%EC%95%84%EC%9D%B4%EC%8A%A4%ED%8B%B0-450x588.png', null::integer, 138::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Paik''s Coffee menu (paikdabang.com)', null::text, array[]::text[]),
