  ('딸기젤라또 레몬스무디', '음료', '상큼한 레몬스무디에 딸기젤라또와 딸기다이스 토핑으로 새콤달콤함이 가득한 스무디', 'https://paikdabang.com/wp-content/uploads/2026/01/%EB%94%B8%EA%B8%B0%EC%A0%A4%EB%9D%BC%EB%98%90-%EB%A0%88%EB%AA%AC%EC%8A%A4%EB%AC%B4%EB%94%94-450x588.png', null::integer, 150::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('우리사과주스', '음료', '새콤달콤한 풍미가 일품인 국내산 사과를 가득 담아낸 과일주스', 'https://paikdabang.com/wp-content/uploads/2026/01/%EC%9A%B0%EB%A6%AC%EC%82%AC%EA%B3%BC%EC%A3%BC%EC%8A%A4-450x588.png', null::integer, 151::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('사과당근주스', '음료', '국내산 사과와 제주 당근의 맛이 다채롭게 느껴지는 주스', 'https://paikdabang.com/wp-content/uploads/2026/01/%EC%82%AC%EA%B3%BC%EB%8B%B9%EA%B7%BC%EC%A3%BC%EC%8A%A4-450x588.png', null::integer, 152::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
