  ('율무라떼(ICED)', '음료', '고소하고 담백한 율무라떼에 바삭한 현미크런치 토핑을 올린 음료', 'https://paikdabang.com/wp-content/uploads/2025/12/%EC%9C%A8%EB%AC%B4%EB%9D%BC%EB%96%BC_ICED-450x588.png', null::integer, 156::integer, array['milk', 'soy', 'wheat']::text[], array[]::text[], array[]::text[], 'Paik''s Coffee menu (paikdabang.com)', null::text, array[]::text[]),
