select r.id, v.* from r, (values
  ('나이트로 바닐라 크림', '콜드 브루', '부드러운 목넘김의 나이트로 커피와 바닐라 크림의 매력을 한번에 느껴보세요!', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002487%5D_20250626171201110.jpg', null::integer, 0::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('나이트로 콜드 브루', '콜드 브루', '(나이트로 콜드 브루 매장 한정) 나이트로 커피 정통의 캐스케이딩과 부드러운 콜드 크레마! 부드러운 목 넘김과 완벽한 밸런스에 커피 본연의 단맛을 경험할 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000000479%5D_20250626095418324.jpg', null::integer, 1::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('돌체 콜드 브루', '콜드 브루', '무더운 여름철, 동남아 휴가지에서 즐기는 커피를 떠오르게 하는 스타벅스 음료의 베스트 x 베스트 조합인 돌체 콜드 브루를 만나보세요!', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002081%5D_20250626100020135.jpg', null::integer, 2::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('리저브 나이트로', '콜드 브루', '나이트로 커피 정통의 캐스케이딩과 부드러운 콜드 크레마! 부드러운 목 넘김과 완벽한 밸런스에 커피 본연의 단맛을 경험할 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/02/%5B9200000002407%5D_20210225095106743.jpg', null::integer, 3::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('리저브 콜드 브루', '콜드 브루', '리저브 커피 마스터의 정성으로 차갑게 추출한 깊고 부드러운 풍미의 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/03/%5B9200000002093%5D_20240318144604476.jpg', null::integer, 4::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('막걸리향 크림 콜드 브루', '콜드 브루', '산에서 만날 수 있는 특별한 경험을 모티브로해 달콤, 향긋한 비알코올 막걸리 향 크림과 고소한 쌀 토핑으로 즐길 수 있는 콜드 브루', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/05/%5B9200000005282%5D_20240509131200017.jpg', null::integer, 5::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('민트 콜드 브루', '콜드 브루', '상쾌한 민트향 시럽과 잘게 갈린 얼음이 어우러져 시원함이 강렬하게 느껴지는 리저브만의 콜드 브루 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/10/%5B9200000004312%5D_20221005145029134.jpg', null::integer, 6::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('바닐라 아인슈페너 콜드 브루', '콜드 브루', '폭신한 바닐라 콜드 폼과 깊은 초콜릿 풍미의 콜드 브루가 만난 스타벅스의 아인슈페너. 음료와 잘 어울리는 스타벅스만의 콜드 폼으로 깔끔한 커피를 색다르게 즐겨보세요. ※ 해당 음료는 ''콜드 폼''이 기본으로 포함되어 제공됩니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9200000006945%5D_20260415131227200.jpg', null::integer, 7::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바닐라 크림 콜드 브루', '콜드 브루', '콜드 브루에 더해진 바닐라 크림으로 깔끔하면서 달콤한 콜드 브루를 새롭게 즐길 수 있는 음료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000000487%5D_20250626095703208.jpg', null::integer, 8::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베르가못 콜드 브루', '콜드 브루', '은은하게 퍼지는 플로럴 향과 베르가못의 화사하고 우아한 시트러스 맛이 느껴지는 부드러운 콜드 브루', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/11/%5B9200000005991%5D_20251125104417629.jpg', null::integer, 9::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('블랙&화이트 콜드 브루', '콜드 브루', '리저브 콜드 브루와 하우스 메이드 바닐라 빈 크림이 어우러진 아인슈페너 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/07/%5B9200000006301%5D_20250703090404091.jpg', null::integer, 10::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('서울 막걸리향 콜드 브루', '콜드 브루', '한국 전통주 ''막걸리’의 향미에서 영감을 받은 비알코올 쌀 베이스에, 스타벅스 콜드 브루의 깊고 부드러운 풍미가 조화를 이루는 새로운 스타일의 서울 특화 콜드 브루', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9200000006938%5D_20260304125135451.jpg', null::integer, 11::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스모크드 콜드 패션드', '콜드 브루', '스모키한 위스키의 풍미와 초콜릿 풍미의 리저브 커피가 어우러진 칵테일처럼 즐기는 콜드 브루 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/04/%5B9200000006056%5D_20250424105540077.jpg', null::integer, 12::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('시그니처 더 블랙 콜드 브루', '콜드 브루', '콜드 브루 전용 원두를 차가운 물로 매장에서 직접 추출하여 부드럽고 진한 풍미의 콜드브루를 언제 어디서나 편하게 즐겨보세요 (전용 보틀 /500ml)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000003661%5D_20250626093642415.jpg', null::integer, 13::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('여수 윤슬 헤이즐넛 콜드 브루', '콜드 브루', '햇빛이나 달빛에 비치어 반짝이는 잔물결이라는 "윤슬"을 형상화한 헤이즐넛 콜드브루', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000004750%5D_20250626093847094.jpg', null::integer, 14::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('오트 콜드 브루', '콜드 브루', '콜드 브루의 풍미와 깔끔한 오트음료(식물성 대체유)가 어우러진 달콤 고소한 라떼. 식물성 대체유를 사용해 모든 고객이 부담없이 즐길 수 있는 콜드 브루 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000003285%5D_20250626095600441.jpg', null::integer, 15::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('제주 비자림 리저브 콜드 브루', '콜드 브루', '리저브 콜드브루에 말차 돌체 베이스를 추가하여 제주 천년의 숲 비자림을 표현한 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B9200000005616%5D_20241014134021881.jpg', null::integer, 16::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('콜드 브루', '콜드 브루', '스타벅스 바리스타의 정성으로 탄생한 콜드 브루! 콜드 브루 전용 원두를 차가운 물로 추출하여 한정된 양만 제공됩니다. 실크같이 부드럽고 그윽한 초콜릿 풍미의 콜드 브루를 만나보세요!', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000004770%5D_20250626175029778.jpg', null::integer, 17::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('콜드 브루 몰트', '콜드 브루', '[리저브 전용음료] 리저브 콜드 브루, 바닐라 아이스크림, 몰트가 블렌딩된 리저브만의 쉐이크', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/02/%5B9200000001636%5D_20210225093600536.jpg', null::integer, 18::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('콜드 브루 플로트', '콜드 브루', '[리저브 전용음료] 리저브 콜드 브루 위에 녹아 내리는 한 스쿱의 바닐라 아이스크림', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/02/%5B9200000001635%5D_20210225092236748.jpg', null::integer, 19::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('프렌치 바닐라 콜드 브루', '콜드 브루', '깊고 부드러운 프렌치 바닐라 풍미와 깔끔한 콜드 브루가 어우러진 음료. 대비되는 옐로우&브라운의 레이어 속에서 달콤한 프렌치 감성을 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9200000006948%5D_20260415131310868.jpg', null::integer, 20::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('브루드 커피', '브루드 커피', '시즌에 어울리는 원두 종류를 선정하여 신선하게 브루드(Brewed)되어 제공되는 드립커피로, 원두 커피의 풍부한 맛과 향을 따뜻하게 즐기실 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B2%5D_20210430111934117.jpg', null::integer, 21::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('스위트 밀크 커피', '브루드 커피', '매장에서 추출한 아이스 커피와 화이트 초콜릿이 어우러진 커피 우유 스타일의 가벼운 드립 커피 라떼 주기적으로 달라지는 브루드 커피 원두와 함께 드립 라떼의 새로운 매력을 느껴보세요', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9200000006852%5D_20260205135209835.jpg', null::integer, 22::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 브루드 커피', '브루드 커피', '시즌에 어울리는 원두 종류를 선정하여 드립 방식으로 추출한 후 얼음과 함께 제공하는 커피로, 원두 커피의 풍부하고 깔끔한 맛을 느끼실 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B106509%5D_20250626092521116.jpg', null::integer, 23::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('스타벅스 에어로카노', '에스프레소', '아메리카노에 바리스타의 기술을 더해 벨벳 같은 미세한 거품층과 부드러운 목넘김을 즐길 수 있는 새로운 스타일의 음료 한층 풍부한 커피 풍미와 물결처럼 흘러내리는 캐스케이딩 비주얼의 에어로카노를 경험해보세요!', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9200000006840%5D_20260205135245242.jpg', null::integer, 24::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('블랙 글레이즈드 라떼', '에스프레소', '가을 시즌 대표 음료! 돌아온 블랙 글레이즈드 라떼 짙고 풍부한 커피와 달콤하고 부드러운 글레이즈드 폼의 조화가 돋보이는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000002259%5D_20260928101559278.jpg', null::integer, 25::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 블랙 글레이즈드 라떼', '에스프레소', '가을 시즌 대표 음료! 돌아온 블랙 글레이즈드 라떼 짙고 풍부한 커피와 달콤하고 부드러운 글레이즈드 폼의 조화가 돋보이는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000002262%5D_20260928101657468.jpg', null::integer, 26::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('에스프레소 콘 파나', '에스프레소', '신선한 에스프레소 샷에 풍부한 휘핑크림을 얹은 커피 음료로서, 뜨거운 커피의 맛과 차갑고 달콤한 생크림의 맛을 같이 즐길 수 있는 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B30%5D_20210415144252244.jpg', null::integer, 27::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('에스프레소 마키아또', '에스프레소', '신선한 에스프레소 샷에 우유 거품을 살짝 얹은 커피 음료로써, 강렬한 에스프레소의 맛과 우유의 부드러움을 같이 즐길 수 있는 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B25%5D_20210415144211211.jpg', null::integer, 28::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 1호점 카페 아메리카노', '에스프레소', '풍부하고 부드러운 바디감의 별다방 블렌드 원두로 내린 에스프레소와 뜨거운 물을 섞어 깔끔하게 즐길 수 있는 스타벅스 이대점만의 블랙 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005514%5D_20240919154516844.jpg', null::integer, 29::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('스타벅스 자몽 허니 에어로카노', '에스프레소', '상큼한 자몽의 풍미와 벨벳같은 미세한 거품으로 부드러운 목넘김이 조화롭게 어우러져 밝고 산뜻하면서도 균형 잡힌 맛을 선사하는 에어로카노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9200000007131%5D_20260729082321315.jpg', null::integer, 30::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 스타벅스 1호점 카페 아메리카노', '에스프레소', '풍부하고 부드러운 바디감의 별다방 블렌드 원두로 내린 에스프레소와 얼음과 물을 섞어 시원하고 깔끔하게 즐길 수 있는 스타벅스 이대점만의 블랙 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005516%5D_20240919154833807.jpg', null::integer, 31::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 카페 아메리카노', '에스프레소', '진한 에스프레소에 시원한 정수물과 얼음을 더한 깊이와 풍미가 살아있는 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110563%5D_20250626094353711.jpg', null::integer, 32::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('카페 아메리카노', '에스프레소', '진한 에스프레소에 뜨거운 물을 더한 깊이와 풍미가 살아있는 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B94%5D_20210430103337006.jpg', null::integer, 33::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 우베 코코넛 마키아또', '에스프레소', '코코넛 베이스에 진한 에스프레소와 부드러운 우베 폼을 더한 음료 크런치한 코코넛칩과 함께 즐길 수 있는 리저브 마키아또', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/05/%5B9200000007089%5D_20260518094337907.jpg', null::integer, 34::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 카라멜 마키아또', '에스프레소', '향긋한 바닐라 시럽과 시원한 우유에 얼음을 넣고 점을 찍듯이 에스프레소를 부은 후 벌집 모양으로 카라멜 드리즐을 올린 달콤한 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110582%5D_20250626095111658.jpg', null::integer, 35::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카라멜 마키아또', '에스프레소', '향긋한 바닐라 시럽과 따뜻한 스팀 밀크 위에 풍성한 우유 거품을 얹고 점을 찍듯이 에스프레소를 부은 후 벌집 모양으로 카라멜 드리즐을 올린 달콤한 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B126197%5D_20210415154609863.jpg', null::integer, 36::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 카푸치노', '에스프레소', '풍부하고 진한 에스프레소에 신선한 우유와 우유 거품이 얼음과 함께 들어간 시원하고 부드러운 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110601%5D_20250626095213930.jpg', null::integer, 37::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카푸치노', '에스프레소', '풍부하고 진한 에스프레소에 따뜻한 우유와 벨벳 같은 우유 거품이 1:1 비율로 어우러져 마무리된 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B38%5D_20210415154821846.jpg', null::integer, 38::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('라벤더 카페 브레베', '에스프레소', '진한 리저브 에스프레소 샷과 은은한 라벤더향이 고급스럽게 어우러진 부드럽고 세련된 풍미의 라벤더 카페 브레베', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/04/%5B9200000004119%5D_20220412083025862.png', null::integer, 39::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('밀크카라멜 라떼', '에스프레소', '부드럽고 달콤한 밀크카라멜의 은은한 풍미와 풍부한 질감을 느낄 수 있는 특별한 우유가 만나 언제나 편안하게 즐길 수 있는 라떼입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000006235%5D_20250604124942828.jpg', null::integer, 40::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바닐라 라떼', '에스프레소', '달콤한 바닐라의 향을 풍부하고 진한 에스프레소, 부드러운 우유와 함께 즐길 수 있는 라떼입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9200000006343%5D_20251029141705796.jpg', null::integer, 41::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바닐라 빈 라떼', '에스프레소', '리저브만을 위한 바닐라 빈 시럽이 부드럽게 어우러진 카페 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/02/%5B9200000001939%5D_20210225094313315.jpg', null::integer, 42::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('번트 카라멜 라떼', '에스프레소', '리저브 에스프레소 커피와 번트 카라멜의 깊고 달콤한 풍미가 어우러진 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B9200000006054%5D_20250514142846184.jpg', null::integer, 43::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('사케라또 비안코 오버 아이스', '에스프레소', '얼음과 같이 쉐이킹하여 차가워진 진한 리저브 에스프레소와 하우스 메이드 크림이 어우러진 달콤한 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/03/%5B9200000002095%5D_20240318144701881.jpg', null::integer, 44::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 1호점 카페 라떼', '에스프레소', '풍부하고 부드러운 바디감의 별다방 블렌드 원두로 내린 에스프레소와 신선한 우유를 스팀하여 커피 위에 우유 거품을 살짝 얹은 스타벅스 이대점만의 카페 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005518%5D_20240919154933695.jpg', null::integer, 45::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 1호점 크림 라떼', '에스프레소', '"Coffee & Tea & Spice"스타벅스 첫번째 로고에서 착안한 음료로 스파이시한 향의 달콤하고 부드러운 커피 차이 크림폼, 풍부한 바디감의 별다방 블렌드 원두를 사용한 깊고 부드러운 크림 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005522%5D_20240919155344866.jpg', null::integer, 46::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 꿀 호떡 라떼', '에스프레소', '한국의 대표 길거리 음식의 친근하고 익숙한 호떡을 형상화한 음료로 어린시절 추억이 느껴지는 커피 음료 시나몬향과 고소한 견과류가 느껴지는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B9200000006164%5D_20250513101130306.jpg', null::integer, 47::integer, array['peanut', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 돌체 라떼', '에스프레소', '스타벅스의 다른 커피 음료보다 더욱 깊은 커피의 맛과 향에 깔끔한 무지방 우유와 부드러운 돌체 시럽이 들어간 음료로 달콤하고 진한 커피 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B128692%5D_20210426091933665.jpg', null::integer, 48::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 라벤더 카페 브레베', '에스프레소', '진한 리저브 에스프레소 샷과 은은한 라벤더향이 고급스럽게 어우러진 부드럽고 세련된 풍미의 라벤더 카페 브레베', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/04/%5B9200000004120%5D_20220412082952150.png', null::integer, 49::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 밀크카라멜 라떼', '에스프레소', '부드럽고 달콤한 밀크카라멜의 은은한 풍미와 풍부한 질감을 느낄 수 있는 특별한 우유가 만나 언제나 편안하게 즐길 수 있는 라떼입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000006238%5D_20250613084659816.jpg', null::integer, 50::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 바닐라 라떼', '에스프레소', '달콤한 바닐라의 향을 풍부하고 진한 에스프레소, 부드러운 우유와 함께 즐길 수 있는 라떼입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9200000006346%5D_20251029141759604.jpg', null::integer, 51::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 바닐라 빈 라떼', '에스프레소', '리저브만을 위한 바닐라 빈 시럽이 부드럽게 어우러진 카페 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/02/%5B9200000001941%5D_20210225094346653.jpg', null::integer, 52::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 스타벅스 1호점 카페 라떼', '에스프레소', '풍부하고 부드러운 바디감의 별다방 블렌드 원두로 내린 에스프레소와 신선한 우유와 얼음이 만나 고소함과 시원함을 즐길 수 있는 스타벅스 이대점만의 카페 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005520%5D_20240919155241283.jpg', null::integer, 53::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 스타벅스 1호점 크림 라떼', '에스프레소', '"Coffee & Tea & Spice"스타벅스 첫번째 로고에서 착안한 음료로 스파이시한 향의 달콤하고 부드러운 커피 차이 크림폼, 풍부한 바디감의 별다방 블렌드 원두를 사용한 깊고 부드러운 크림 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9200000005523%5D_20240919155443058.jpg', null::integer, 54::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 스타벅스 꿀 호떡 라떼', '에스프레소', '한국의 대표 길거리 음식의 친근하고 익숙한 호떡을 형상화한 음료로 어린시절 추억이 느껴지는 커피 음료 시나몬향과 고소한 견과류가 느껴지는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B9200000006165%5D_20250513101211857.jpg', null::integer, 55::integer, array['peanut', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 스타벅스 돌체 라떼', '에스프레소', '스타벅스의 다른 커피 음료보다 더욱 깊은 커피의 맛과 향에 깔끔한 무지방 우유와 부드러운 돌체 시럽이 들어간 음료로 달콤하고 진한 커피 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B128695%5D_20250626095651684.jpg', null::integer, 56::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 인절미 크림 라떼', '에스프레소', '고소하고 쌉싸름한 맛의 콩고물과 쫀득한 식감의 인절미 젤리를 달콤한 크림이 얹어진 커피와 함께 즐길 수 있는 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/05/%5B9200000005285%5D_20240509131125335.jpg', null::integer, 57::integer, array['peanut', 'soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 카페 라떼', '에스프레소', '풍부하고 진한 에스프레소에 시원한 우유를 더해 부드럽게 즐길 수 있는 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110569%5D_20250626094801903.jpg', null::integer, 58::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('인절미 크림 라떼', '에스프레소', '고소하고 쌉싸름한 맛의 콩고물과 쫀득한 식감의 인절미 젤리를 달콤한 크림이 얹어진 커피와 함께 즐길 수 있는 라떼', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/05/%5B9200000005284%5D_20240509131037171.jpg', null::integer, 59::integer, array['peanut', 'soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 비자림 리저브 에스프레소 라떼', '에스프레소', '리저브 원두로 만든 라떼에 말차 돌체 베이스를 추가하여 제주 천년의 숲 비자림을 표현한 라떼. 오직 송당에서만 만날 수 있는 음료로, 따뜻한 비자림의 풍미를 느껴보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9200000006575%5D_20251013103821201.jpg', null::integer, 60::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카페 라떼', '에스프레소', '풍부하고 진한 에스프레소가 신선한 스팀 밀크를 만나 부드러워진 커피 위에 우유 거품을 살짝 얹은 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B41%5D_20210415133833725.jpg', null::integer, 61::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('코르타도', '에스프레소', '진하면서도 부드러운 블론드 리스트레토 3샷에 폼을 살짝 낸 스팀 밀크를 더해 짙은 커피 풍미를 즐길 수 있는 코르타도입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9200000006338%5D_20251029141124907.jpg', null::integer, 62::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('피넛 크림 쿠키 아인슈페너', '에스프레소', '제주의 고소함을 가득 담은 시그니처 피넛 아인슈페너의 등장! 진한 땅콩 풍미에 에스프레소를 더하고, 땅콩 크림과 너티 쿠키로 완성한 제주 특화 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9200000006976%5D_20260421123846098.jpg', null::integer, 63::integer, array['peanut', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 카페 모카', '에스프레소', '진한 초콜릿 모카 시럽과 풍부한 에스프레소를 신선한 우유 그리고 얼음과 섞어 휘핑크림으로 마무리한 음료로 진한 에스프레소와 초콜릿 맛이 어우러진 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110566%5D_20250626113005628.jpg', null::integer, 64::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 화이트 초콜릿 모카', '에스프레소', '달콤하고 부드러운 화이트 초콜릿 시럽과 에스프레소를 신선한 우유 그리고 얼음과 섞어 휘핑크림으로 마무리한 음료로 달콤함과 강렬한 에스프레소가 부드럽게 어우러진 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110572%5D_20250626113205748.jpg', null::integer, 65::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카페 모카', '에스프레소', '진한 초콜릿 모카 시럽과 풍부한 에스프레소를 스팀 밀크와 섞어 휘핑크림으로 마무리한 음료로 진한 에스프레소와 초콜릿 맛이 어우러진 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B46%5D_20210415134438165.jpg', null::integer, 66::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('클래식 민트 모카', '에스프레소', '스타벅스의 클래식인 페퍼민트 모카를 떠올리게 하는 리저브만의 에스프레소 음료 오트음료(식물성 대체유)의 고소함과 다크 초콜릿의 쌉쌀함이 특징인 음료입니다', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/10/%5B9200000004313%5D_20221005145156959.jpg', null::integer, 67::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('화이트 초콜릿 모카', '에스프레소', '달콤하고 부드러운 화이트 초콜릿 시럽과 에스프레소를 스팀 밀크와 섞어 휘핑크림으로 마무리한 음료로 달콤함과 강렬한 에스프레소가 부드럽게 어우러진 커피', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B128192%5D_20210415155639126.jpg', null::integer, 68::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 플랫 화이트', '에스프레소', '부드러운 리스트레토 샷과 완벽한 양의 우유를 더해, 카페 라떼보다 커피의 맛을 진하게 즐길 수 있는 에스프레소 음료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000005181%5D_20250626095819133.jpg', null::integer, 69::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('플랫 화이트', '에스프레소', '부드러운 리스트레토 샷과 완벽한 양의 스팀밀크를 더해, 카페 라떼보다 커피의 맛을 진하게 즐길 수 있는 에스프레소 음료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/03/%5B9200000005178%5D_20240326103727795.jpg', null::integer, 70::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바닐라 스타벅스 더블 샷', '에스프레소', '신선하게 제조된 더블 샷 믹스에 바닐라 시럽을 넣고 에스프레소 샷, 얼음이 어우러져 핸드 쉐이킹한 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110612%5D_20250626095701777.jpg', null::integer, 71::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('사케라또 아포가토', '에스프레소', '민트 잎과 쉐이킹한 리저브 에스프레소를 바닐라 아이스크림에 부어 프레쉬함과 달콤함이 조화롭게 퍼지는 리저브 만의 디저트 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/03/%5B9200000003505%5D_20210322093241535.jpg', null::integer, 72::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스파클링 시트러스 에스프레소', '에스프레소', '리저브 에스프레소에 상큼한 레몬과 진저에일을 더해 청량감과 시트러스 풍미를 가득 선사하는 커피 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/03/%5B9200000003506%5D_20210322093317854.jpg', null::integer, 73::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
