  ('더블 에스프레소 칩 프라푸치노', '프라푸치노', '리스트레토 에스프레소 2샷과 에스프레소 칩, 하프앤하프가 진하게 어우러진 커피의 기본에 충실한 프라푸치노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002760%5D_20250626095415811.jpg', null::integer, 80::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 꿀 호떡 크림 프라푸치노', '프라푸치노', '한국의 대표 길거리 음식의 친근하고 익숙한 호떡을 형상화한 음료로 어린시절 추억을 느끼며, 시나몬향과 고소한 견과류를 더욱 시원하게 즐길 수 있는 프라푸치노 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000006303%5D_20250619133012310.jpg', null::integer, 81::integer, array['peanut', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('에스프레소 프라푸치노', '프라푸치노', '풍부하고 진한 에스프레소 샷의 강렬함과 달콤함이 어우러져 깊은 커피의 풍미를 느낄 수 있는 프라푸치노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B168007%5D_20250626095952087.jpg', null::integer, 82::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('자바 칩 프라푸치노', '프라푸치노', '커피, 모카 소스, 진한 초콜릿 칩이 입안 가득 느껴지는 스타벅스에서만 맛볼 수 있는 프라푸치노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B168016%5D_20250626113600873.jpg', null::integer, 83::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카라멜 프라푸치노', '프라푸치노', '카라멜과 커피가 어우러진 프라푸치노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B168010%5D_20250626113443023.jpg', null::integer, 84::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('딸기 글레이즈드 크림 프라푸치노', '프라푸치노', '상큼&달콤한 딸기와 부드러운 글레이즈드 소스에 바삭한 딸기 토핑을 얹은 프라푸치노. 숙련된 바리스타의 솜씨로 그려낸 특별한 예술 작품을 감상해보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/06/%5B9200000005369%5D_20240614143554454.jpg', null::integer, 85::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베르가못 딸기 크림 프라푸치노', '프라푸치노', '여름 수국의 사랑스러운 색감을 형상화한 음료로 은은하게 퍼지는 얼그레이의 플로럴향과 딸기의 상큼한 풍미가 느껴지는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/07/%5B9200000006304%5D_20250708105445804.jpg', null::integer, 86::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베르가못 제주 말차 크림 프라푸치노', '프라푸치노', '자연과 어우러진 수국의 색감을 형상화한 음료로 제주산 말차와 함께 은은하게 퍼지는 얼그레이의 플로럴향으로 부드러운 맛을 즐길 수 있는 음료 (제주산 말차)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000006305%5D_20250619141412982.jpg', null::integer, 87::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 까망 크림 프라푸치노', '프라푸치노', '쫄깃한 흑임자 떡과 블랙 소보로 토핑으로 컵빙수처럼 먹는 음료. 고소한 흑임자와 쫄깃한 흑임자 떡, 달콤한 블랙 소보로 토핑으로 제주의 돌 하르방 길을 느낄 수 있는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002088%5D_20250626114629418.jpg', null::integer, 88::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat', 'squid']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 말차 크림 프라푸치노', '프라푸치노', '깊고 진한 말차 본연의 맛과 향을 시원하고 부드럽게 즐길 수 있는 프라푸치노', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002502%5D_20250626100915378.jpg', null::integer, 89::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 쑥떡 크림 프라푸치노', '프라푸치노', '[제주지역 한정음료] 쫄깃쫄깃한 흑임자 떡으로 씹는 재미를 즐길 수 있는 음료로, 고소한 흑임자와 쑥떡 토핑이 올라간 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000002090%5D_20250626114614395.jpg', null::integer, 90::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
