  ('망고 패션 프루트 블렌디드', '블렌디드', '망고 패션 프루트 주스와 블랙 티가 깔끔하게 어우러진 과일 블렌디드', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B167004%5D_20250626095805229.jpg', null::integer, 95::integer, array['soy']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('북한산 레몬 얼 그레이 블렌디드', '블렌디드', '꼬냑 향을 가미한 상큼한 레모네이드와 은은한 얼 그레이 티가 어우러진 블렌디드 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9200000004716%5D_20261006112253581.jpg', null::integer, 96::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('스타벅스 클래식 밀크티 블렌디드', '블렌디드', '블랙티의 풍미와 향이 더욱 풍요롭게 느껴질 수 있는 밀크티 블렌디드', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/08/%5B9200000004945%5D_20250827131549415.jpg', null::integer, 97::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('여수 바다 유자 블렌디드', '블렌디드', '맑고 깨끗한 여수 경도의 낮 바다 풍경을 형상화한 음료로 상큼하게 즐길 수 있는 유자 블렌디드 음료 (유자:국내산)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9200000004870%5D_20260731110244613.jpg', null::integer, 98::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
