  ('딸기 딜라이트 요거트 블렌디드', '블렌디드', '고농축 유산균의 부드러운 요거트와 딸기 본연의 상콤&달콤한 과육이 상큼하게 어우러진 리뉴얼 된 과일 요거트 블렌디드', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/07/%5B9200000003276%5D_20250721084027663.jpg', null::integer, 100::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('말차 폭포 유자 블렌디드', '블렌디드', '쏟아지는 폭포를 표현한 말차와 상큼한 유자 캐모마일 티가 만나 시원한 평화를 선사하는 송당만의 과일 티 블렌디드 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9200000006577%5D_20251013103946321.jpg', null::integer, 101::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('망고 바나나 블렌디드', '블렌디드', '(Grande Only) 달콤한 망고 패션 프루트 주스에 바나나 1개가 통째로 들어간 신선한 블렌디드', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B169001%5D_20250626100121981.jpg', null::integer, 102::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('블랙 글레이즈드 셔벗 플레이트', '블렌디드', '마스카포네 크림을 얹은 에스프레소 셔벗과 리저브 에스프레소를 함께, 또 따로 아포가토처럼 즐기는 디저트 스타일 셔벗 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9200000006941%5D_20260324151120249.jpg', null::integer, 103::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('블루베리 딜라이트 요거트 블렌디드', '블렌디드', '고농축 유산균의 부드러운 요거트와 달콤한 블루베리가 부드럽게 어우러진 시원한 과일 요거트 블렌디드', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9200000006963%5D_20260714082039571.jpg', null::integer, 104::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('자몽 허니 레몬 블렌디드', '블렌디드', '제로 시럽을 활용해 칼로리 부담을 낮추고, 달콤한 자몽 허니에 레몬을 더해 가볍고 상큼하게 즐길 수 있는 과일 블렌디드 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/09/%5B9200000006466%5D_20250904105105974.jpg', null::integer, 105::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('피치 망고 블렌디드', '블렌디드', '오직 강릉에서만 다시 만날 수 있는 특화 음료로, 달콤한 피치,망고에 산뜻한 히비스커스 티를 더한 매력적인 음료 *G Only', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/06/%5B9200000004780%5D_20260604081230816.jpg', null::integer, 106::integer, array['soy', 'peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('딸기 아사이 레모네이드 스타벅스 리프레셔', '리프레셔', '딸기, 아사이베리 주스와 레모네이드가 달콤 상큼하게 조화된 맛에 가볍게 에너지 부스팅을 할 수 있는 리프레셔 음료.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000004753%5D_20250626175350251.jpg', null::integer, 107::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('핑크 피치 리프레셔', '리프레셔', '피치, 망고, 딸기 등의 다양한 과일 플레이버와 레모네이드가 조화롭게 어우러진 리프레셔 음료 두 가지 핑크 톤의 레이어와 함께 가볍게 에너지 부스팅 할 수 있는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/06/%5B9200000007097%5D_20260619142429847.jpg', null::integer, 108::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('유자 V 피지오', '피지오', '상큼한 유자와 헤스페리딘을 담아 청량하게 즐기기 좋은 피지오. 걷기 좋은 날, 많이 걸은 날 리프레시 하기 좋은 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000007155%5D_20260928104553674.jpg', null::integer, 109::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('유자 말차 V 피지오', '피지오', '상큼한 유자와 제주산 말차를 청량하게 즐길 수 있는 피지오. 가벼운 하루를 부스트 업 시키고 싶을 때 즐기기 좋은 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000007152%5D_20260928104430399.jpg', null::integer, 110::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('골든 만다린 홉 피지오', '피지오', '부드럽게 느껴지는 티폼과 시트러스한 감귤 풍미 맥주 느낌의 청량하게 즐기는 상큼한 피지오 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B9200000006172%5D_20250513101034691.jpg', null::integer, 111::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('라이트 핑크 자몽 피지오', '피지오', '달콤 쌉싸름한 자몽에 탄산의 청량감을 가득 담은 피지오로, 2018년 대비 칼로리를 60% 낮춰 돌아왔습니다. *G사이즈 기준 99kcal 이하 *18년 대비 칼로리 60% DOWN', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000005168%5D_20250626095609681.jpg', null::integer, 112::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('리버 피치 피지오', '피지오', '길고 깊은 강의 모습과 달콤한 복숭아가 만나 강의 뷰를 즐기며 힐링할 수 있는 상큼한 피지오', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/05/%5B9200000005283%5D_20240509131233446.jpg', null::integer, 113::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('서울 석양 오미자 피지오', '피지오', '궁궐 연못을 형상화하는 파랑색 라임 에이드와, 진한 석양을 형상화 하는 상큼한 오미자 용과 피지오가 섞여 아름다운 보랏빛으로 변하는 서울 특화 피지오', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9200000006937%5D_20260304125026093.jpg', null::integer, 114::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('여수 바다 자몽 피지오', '피지오', '여수 돌산대교의 밤바다 풍경을 형상화한 음료로 알록달록 색상 조명의 토핑과 함께 여수의 풍경을 바라보며 즐길 수 있는 트로피컬 맛의 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2023/09/%5B9200000004751%5D_20230907153225204.jpg', null::integer, 115::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('의암호의 초록빛 자몽 피지오', '피지오', '춘천의암호 낮의 싱그러운 초록빛을 형상화한 음료로 청자몽과 라임, 레몬젤리를 활용한 피지오 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B9200000005588%5D_20241017130009134.jpg', null::integer, 116::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('제주팔삭 셔벗 피지오', '피지오', '제주송당의 소원나무에 걸린 제주 동백꽃을 형상화한 음료 제주의 자몽이라는 별명을 가진 제주 팔삭과 제주 한라봉으로 매장에서 직접 만든 셔벗과 함께 상큼하게 즐길 수 있는 피지오 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/01/%5B9200000004946%5D_20240103144959834.jpg', null::integer, 117::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('제주팔삭 피지오', '피지오', '제주의 자몽이라는 별명을 가진 팔삭과 제주 한라봉으로 상큼하고 가볍게 즐길 수 있는 피지오 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/08/%5B9200000004947%5D_20250827131344272.jpg', null::integer, 118::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('체리&자두 에너지 피지오', '피지오', '체리와 자두의 이색 조합으로 그란데 사이즈 99kcal와 타우린과 비타민C 등이 영양소가 함유되어 건강한 에너지를 시원하게 즐길 수 있는 카페인 프리 음료. (필요 시 무료로 블랙 티 커스텀을 통해 카페인도 추가할 수 있습니다)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/07/%5B9200000005983%5D_20250724154622363.jpg', null::integer, 119::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('쿨 라임 피지오', '피지오', '그린 빈 추출액이 들어간 라임 베이스에 건조된 라임 슬라이스를 넣고 스파클링한 시원하고 청량감 있는 음료입니다. (카페인이 함유된 탄산음료입니다)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B107051%5D_20250626093749068.jpg', null::integer, 120::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('피치 딸기 피지오', '피지오', '피치와 딸기의 상큼한 과일과 청량한 탄산의 조화로 리프레시 할 수 있는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/11/%5B9200000004567%5D_20251125104447608.jpg', null::integer, 121::integer, array['peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 퓨어 말차', '티', '깨끗한 정수에 100% 제주산 녹찻잎을 곱게 갈아 완성한 말차. 차광 재배한 제주산 녹찻잎을 곱게 갈아 말차 본연의 깔끔한 맛과 향을 즐길 수 있는 음료.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9200000007158%5D_20261001123512465.jpg', null::integer, 122::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 퓨어 호지차', '티', '깨끗한 정수에 100% 국내산 호지차만을 담은 음료. 호지차 본연의 고소한 풍미와 깊은 향을 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9200000007184%5D_20261001123958037.jpg', null::integer, 123::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('퓨어 말차', '티', '깨끗한 정수에 100% 제주산 녹찻잎을 곱게 갈아 완성한 말차. 차광 재배한 제주산 녹찻잎을 곱게 갈아 말차 본연의 깔끔한 맛과 향을 즐길 수 있는 음료.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9200000007178%5D_20261001123642175.jpg', null::integer, 124::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('퓨어 호지차', '티', '깨끗한 정수에 100% 국내산 호지차만을 담은 음료. 호지차 본연의 고소한 풍미와 깊은 향을 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9200000007181%5D_20261001123852597.jpg', null::integer, 125::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('글레이즈드 폼 블랙 티', '티', '깊고 맑은 블랙 티에 부드러운 치즈 풍미의 글레이즈드 폼을 더한 스타벅스만의 폼 티(Foam Tea). 알로에 토핑의 산뜻한 식감이 더해져 풍부한 맛과 다채로운 식감을 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000007173%5D_20260910142947420.jpg', null::integer, 126::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('말차 글레이즈드 티 라떼', '티', '글레이즈드의 색다른 변신! 쌉싸름한 말차와 달콤한 글레이즈드를 넣어 가을과 잘 어울리는 비주얼과 맛의 티 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000006412%5D_20260910142648343.jpg', null::integer, 127::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 말차 글레이즈드 티 라떼', '티', '글레이즈드의 색다른 변신! 쌉싸름한 말차와 달콤한 글레이즈드를 넣어 가을과 잘 어울리는 비주얼과 맛의 티 라떼 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000006415%5D_20260910142754201.jpg', null::integer, 128::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 호지 글레이즈드 티 라떼', '티', '국내산 호지차로 만든 티 라떼에 글레이즈드 폼을 올린 음료. 고소한 호지차에 치즈 풍미를 더한 글레이즈드 폼이 어우러져 색다른 맛을 즐길 수 있는 음료.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000007164%5D_20260928103930887.jpg', null::integer, 129::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('호지 글레이즈드 티 라떼', '티', '국내산 호지차로 만든 티 라떼에 글레이즈드 폼을 올린 음료. 고소한 호지차에 치즈 풍미를 더한 글레이즈드 폼이 어우러져 색다른 맛을 즐길 수 있는 음료.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9200000007161%5D_20260928103330438.jpg', null::integer, 130::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('민트 블렌드 티', '티', '스피어민트, 페퍼민트, 레몬머틀이 블렌딩된 상쾌한 허브 티', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B4004000000056%5D_20210415135215632.jpg', null::integer, 131::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 민트 블렌드 티', '티', '스피어민트, 페퍼민트, 레몬머틀이 블렌딩된 상쾌한 허브 티', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B4004000000059%5D_20250626095245748.jpg', null::integer, 132::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 얼 그레이 티', '티', '꽃향 가득한 라벤더와 베르가못 향이 진한 홍차와 블렌딩된 향긋한 블랙 티', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B4004000000039%5D_20250626095101523.jpg', null::integer, 133::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 유스베리 티', '티', '제주산 찻잎으로 만든 황차에 사과, 망고, 파인애플, 히비스커스, 로즈힙 등이 블렌딩되어 핑크빛 컬러가 감도는 수색과 베리류의 새콤함을 느낄 수 있는 옐로우 티', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000000229%5D_20250626094905408.jpg', null::integer, 134::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
