  ('시그니처 핫 초콜릿', '기타', '깊고 진한 초콜릿과 부드러운 휘핑크림이 입안에서 사르르 녹는 초콜릿 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B72%5D_20210415140949967.jpg', null::integer, 171::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아이스 시그니처 초콜릿', '기타', '깊고 진한 초콜릿과 부드러운 휘핑크림이 입안에서 사르르 녹는 초콜릿 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B110621%5D_20250626113323062.jpg', null::integer, 172::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
