  ('딸기 콜드폼 딸기 라떼', '기타', '딸기 풍미 가득한 스타벅스만의 딸기 콜드폼과 딸기 본연의 맛을 즐길 수 있는 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2023/11/%5B9200000004951%5D_20231102101647442.jpg', null::integer, 177::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 슬래머', '기타', '스트로베리와 아사이베리의 상큼, 달콤한 맛이 톡톡! 시원하고 통쾌한 그랜드 슬램을 위한 에너지 부스팅 음료~! * SSG랜더스필드 매장에서만 판매하는 음료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/06/%5B9200000003659%5D_20250626093348421.jpg', null::integer, 178::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
