  ('딸기주스 190ML', '올가니카', '달콤한 국내산 딸기의 과육이 듬뿍 느껴지는 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B5210008070%5D_20250527081742210.jpg', null::integer, 185::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('망고주스 190ML', '올가니카', '노랗게 익은 열대과일 망고가 입안 가득 느껴지는 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B5210008061%5D_20241031123748556.jpg', null::integer, 186::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('수박 주스 190ML', '올가니카', '동남아의 땡모반과 같이 수박 특유의 달콤함과 청량함이 입안 가득 느껴지는 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9300000005405%5D_20240905084714529.jpg', null::integer, 187::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('유기농 오렌지 100% 주스 190ML', '올가니카', '프리미엄 유기농 오렌지 주스로 스페인산 오렌지 착즙! 오렌지 그대로 100% 담긴 3개 분량 물, 설탕, 첨가물 없는 오렌지 그대로의 맛', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9300000003771%5D_20240923184306693.jpg', null::integer, 188::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('케일&사과주스 190ML', '올가니카', '국내산 케일과 사과의 달콤함이 조화로운 녹색 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B5210008072%5D_20210426100712780.jpg', null::integer, 189::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('한라봉주스 190ML', '올가니카', '새콤달콤한 황금빛 제주 한라봉을 그대로 담아낸 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B5210008055%5D_20241031123524702.jpg', null::integer, 190::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('햇사과 주스 190ML', '올가니카', '달콤새콤한 햇사과 1개 반을 껍질 그대로 착즙한 사과 주스', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9300000002565%5D_20240923184651121.jpg', null::integer, 191::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('딸기 가득 요거트 190ML', '올가니카', '상큼 달콤 딸기 과육이 한가득 씹히는 마시는 요거트 음료', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/10/%5B9300000003775%5D_20211020094208342.jpg', null::integer, 192::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('블루베리 요거트 190ML', '올가니카', '블루베리 과육이 입안 가득 느껴지는 마시는 요거트', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B5210008063%5D_20240923185114500.jpg', null::integer, 193::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('찰떡콩떡 베이글', '베이커리', '달콤한 삼색 콩 찰떡을 호두 베이글 속에 가득 채워, 쫀득하고 부드러운 식감과 달콤 고소함이 조화로운 베이글입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006830%5D_20260910143804575.jpg', null::integer, 194::integer, array['walnut', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('탕종 블루베리 베이글', '베이커리', '달콤한 블루베리와 탕종법으로 반죽한 후 고온에서 데치고, 짧게 구워 내 쫄깃하고 촉촉한 식감이 특징인 블루베리 베이글입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2023/09/%5B9300000004823%5D_20230911131337120.jpg', null::integer, 195::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
