  ('트리플 치즈 베이글', '베이커리', '쫄깃한 베이글 안에 고소한 모짜렐라 치즈와 에멘탈 치즈가 들어가고 체다 치즈를 토핑해 짭짤하고 고소한 향이 가득한 베이글입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/12/%5B9300000006230%5D_20251231080903631.jpg', null::integer, 197::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('잉글리쉬 스콘', '베이커리', '고메 버터의 풍미가 은은하게 맴도는 담백한 스콘입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/11/%5B9300000005663%5D_20241106163602619.jpg', null::integer, 198::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('피넛 쑥 떡 스콘', '베이커리', '쫄깃한 떡을 넣은 쑥 스콘 위에 땅콩을 넣은 소보로를 올린 달콤하고 고소한 스콘입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/03/%5B9300000004028%5D_20220314152820975.jpg', null::integer, 199::integer, array['peanut', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('K-에그 바이트', '베이커리', '은은한 단맛이 감도는 부드러운 빵 위에 국내산 달걀 흰자와 체다 & 모짜렐라 치즈, 베이컨으로 고소함과 풍미를 더한 고단백 간편 푸드입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9300000006508%5D_20260313092909738.jpg', null::integer, 200::integer, array['soy', 'milk', 'egg', 'wheat', 'pork']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('거문 오름 크루아상', '베이커리', '[제주지역 한정푸드] 제주도의 현무암을 크루아상에 오름 모양을 아몬드 페이스트로 형상화하여만든 크루아상입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000001361%5D_20210421133918737.jpg', null::integer, 201::integer, array['soy', 'milk', 'egg', 'wheat', 'squid']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('글레이즈드 도넛', '베이커리', '부드러운 식감과 달콤한 맛이 매력적인 링 도넛입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/01/%5B9300000005768%5D_20250102151619801.jpg', null::integer, 202::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('미니 리프 파이', '베이커리', '나뭇잎 모양의 달콤하고 바삭한 파이입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/02/%5B9300000004008%5D_20220218143920309.jpg', null::integer, 203::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바게트 소금빵', '베이커리', '기존 대비 버터 함량을 높여 더욱 깊어진 풍미, 바삭한 겉면과 부드럽고 쫄깃한 식감, 짭조롬한 소금이 어우러져 더 맛있어진 바게트 소금빵입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006831%5D_20260820125137656.jpg', null::integer, 204::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('번트 크림치즈 브레드', '베이커리', '부드럽고 폭신한 빵 속에 크림치즈를 채워 진하게 구워 낸, 색다른 매력의 크림치즈 브레드입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9300000006480%5D_20260313093013865.jpg', null::integer, 205::integer, array['soy', 'milk', 'egg', 'wheat', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('우리 찹쌀 꽈배기', '베이커리', '국내산 찹쌀이 들어있는 쫀득한 식감의 꽈배기입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9300000006492%5D_20260223082257984.jpg', null::integer, 206::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('주상절리 파이', '베이커리', '[제주지역 한정푸드] 제주의 주상절리 모양을 표현하여 겹겹이 쌓은 패스츄리를 바삭하게 구운 후 초콜릿을 입혀 달콤하게 즐길 수 있는 제주 전용 파이입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000002489%5D_20210421134243043.jpg', null::integer, 207::integer, array['soy', 'milk', 'wheat', 'squid']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('쫄깃 소시지 브레드', '베이커리', '돌돌 말린 쫄깃한 도우와 육즙 가득 두툼한 소시지, 어니언 소스가 잘 어우러지는 세이보리 브레드입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/05/%5B9300000006537%5D_20260527080535711.jpg', null::integer, 208::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('하트 파이', '베이커리', '하트 모양의 바삭한 파이입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B5110006070%5D_20210422111451589.jpg', null::integer, 209::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('골든 펌킨 크림 치즈 케이크', '케이크', '가을 대표 식재료인 단호박을 담은 치즈케이크. 달콤한 단호박과 진한 치즈케이크에 쿠키 크럼블이 더해져 풍부한 식감을 즐길 수 있는 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006871%5D_20260910143631424.jpg', null::integer, 210::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('마롱 몽블랑 치즈 케이크', '케이크', '국내산 밤을 넣은 마롱 치즈 케이크 위에 부드러운 생크림, 달콤한 몽블랑 크림을 층층이 쌓아 올린 가을 시즌 한정 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006186%5D_20260928095207564.jpg', null::integer, 211::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('블랙 글레이즈드 부생카', '케이크', '고객들에게 꾸준히 사랑받아 온 부드러운 생크림 카스텔라에 스타벅스 인기 시즌 음료 블랙 글레이즈드 라떼의 매력을 담았습니다. 부드러운 글레이즈드 크림과 진한 모카 초코 크림이 어우러져 깊은 풍미를 즐길 수 있는 부생카입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006870%5D_20260928100853538.jpg', null::integer, 212::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('얼 그레이 카라멜 넛츠 케이크', '케이크', '부드러운 얼 그레이 시트 속 부드러운 마스카포네 생크림과 향긋한 얼 그레이 크림이 조화롭게 어우러지는 가을 시즌 케이크 입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006817%5D_20260928095016062.jpg', null::integer, 213::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('더 멜론 오브 샤인 케이크', '케이크', '멜론과 샤인머스캣을 한 번에 즐길 수 있는 시즌 케이크로, 부드러운 생크림과 어우러진 두 과일의 산뜻하고 달콤한 풍미가 매력입니다. 소중한 이들에게 작은 선물이 필요한 순간을 위해 준비한 미니 홀케이크입니다. 생일, 기념일은 물론 감사의 마음을 전할 때도 가볍게 즐기기 좋은 사이즈입니다. (지름 11cm, 중량 276g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006869%5D_20260825095237251.jpg', null::integer, 214::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('브륄레 쿠키 치즈케이크', '케이크', '달콤한 브륄레 토핑을 더한 치즈 케이크로, 진한 치즈 케이크와 고소한 쿠키, 달콤한 브륄레를 함께 즐기는 케이크입니다. 소중한 이들에게 작은 선물이 필요한 순간을 위해 준비한 미니 홀케이크입니다. 생일, 기념일은 물론 감사의 마음을 전할 때도 가볍게 즐기기 좋은 사이즈입니다. (지름 11cm, 중량 380g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006822%5D_20260825095357293.jpg', null::integer, 215::integer, array['soy', 'milk', 'egg', 'wheat', 'beef']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('모찌 품은 바스크 치즈 케이크', '케이크', '쫀득한 모찌를 품은 부드러운 바스크 치즈 케이크로, 진한 치즈 풍미와 쫀득한 식감을 동시에 느낄 수 있는 케이크입니다. (지름 14.5cm / 중량 630g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006889%5D_20260909162756087.jpg', null::integer, 216::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('보늬밤 몽블랑 치즈 케이크', '케이크', '은은한 밤 풍미의 치즈 케이크 위에 부드러운 마스카포네 크림, 달콤한 몽블랑 크림과 보늬밤을 올려 마무리한 케이크 입니다. (지름 14.3cm / 중량 600g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006891%5D_20260923141831744.jpg', null::integer, 217::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('고구마 카스텔라 생크림 케이크', '케이크', '부드러운 고구마 무스 사이에 고구마 다이스로 고구마 풍미를 가득 담아 생크림을 샌드하고 카스텔라 가루를 듬뿍 올린 달콤하고 고소한 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/12/%5B9300000006218%5D_20251231081030365.jpg', null::integer, 218::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('딸기 촉촉 초코 생크림 케이크', '케이크', '촉촉한 초코 카스텔라 안에 달콤한 가나슈 생크림을 듬뿍 담은 뒤 우유 생크림과 딸기로 상단에 토핑을 한 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/02/%5B9300000005594%5D_20250205141352684.jpg', null::integer, 219::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('레이디핑거 티라미수 케이크', '케이크', '진한 풍미의 마스카포네 치즈 크림 사이에 커피 시럽으로 촉촉하게 적신 레이디핑거 쿠키가 샌드되어 부드럽게 어우러지는 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/12/%5B9300000005607%5D_20241216090249007.jpg', null::integer, 220::integer, array['soy', 'milk', 'egg', 'wheat', 'pork']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('모찌 쏙 바스크 치즈 케이크', '케이크', '쫀득한 모찌를 품은 부드러운 바스크 치즈 케이크로, 플레인과 초코 두 가지 맛이 어우러져 다채로운 풍미를 느낄 수 있는 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9300000006609%5D_20260727102747891.jpg', null::integer, 221::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바나나 푸딩 케이크', '케이크', '바나나 푸딩의 매력을 담은 부드러운 바나나 크림과 달콤한 바나나 슬라이스, 고소한 쿠키 크럼블이 층층이 어우러져 꾸덕한 식감과 깊은 풍미를 즐길 수 있는 떠먹는 디저트 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006873%5D_20260805083656256.jpg', null::integer, 222::integer, array['soy', 'milk', 'egg', 'wheat', 'pork']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('부드러운 생크림 카스텔라', '케이크', '부드러운 생크림이 듬뿍 들어있는 촉촉한 카스텔라입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B5110007181%5D_20210421164728509.jpg', null::integer, 223::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('블루베리 마블 치즈 케이크', '케이크', '촉촉한 블루베리가 콕콕 박힌 진한 풍미의 치즈 케이크로 달콤 상큼한 블루베리가 조화롭게 어우러지는 치즈 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/09/%5B9300000005472%5D_20240926125201748.jpg', null::integer, 224::integer, array['soy', 'milk', 'egg', 'wheat', 'beef', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스트로베리 타르트', '케이크', '입안 가득 퍼지는 고소한 타르트와 촉촉한 크림, 풍성한 딸기 토핑이 조화를 이루는 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9300000006282%5D_20260219130524401.jpg', null::integer, 225::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('초코 품은 부생카', '케이크', '초코가 더해진 촉촉한 투톤 컬러의 카스텔라에 부드러운 생크림, 초코 생크림 두 가지 매력을 한번에 즐길 수 있어 더욱 매력적인 부생카입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/03/%5B9300000005769%5D_20250304112847520.jpg', null::integer, 226::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('초콜릿 크런치 케이크', '케이크', '진한 초콜릿 풍미로 가득한 가나슈 크림을 케이크 시트 사이에 샌드하고 초콜릿 크런치 볼로 바삭한 식감을 살린 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9300000006565%5D_20260313093132335.jpg', null::integer, 227::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('당근 현무암 케이크', '케이크', '현무암을 연상케 하는 오징어 먹물 케이크 시트 사이에 새콤한 당근 크림치즈 무스를 샌드한 컵 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000001055%5D_20210421133631796.jpg', null::integer, 228::integer, array['soy', 'milk', 'egg', 'wheat', 'squid', 'pork']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 녹차 생크림 롤', '케이크', '녹차 롤 케이크 시트에 진한 마스카포네 크림과 달콤 쌉싸름한 제주 녹차 가나슈를 넣은 롤 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/07/%5B9300000003468%5D_20210727081659217.jpg', null::integer, 229::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 땅콩 생크림 롤', '케이크', '롤 케이크 시트에 땅콩을 넣은 진한 마스카포네 크림과 고소한 제주산 땅콩 가나슈을 넣은 후 고소한 카라멜 땅콩을 올린 롤 케이크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/07/%5B9300000003469%5D_20210727081817626.jpg', null::integer, 230::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베어리스타 우유 생크림 케이크', '케이크', '달콤하고 고소한 우유 생크림 안에 바삭하게 씹히는 화이트 초콜릿 볼이 쏙쏙 박혀 있는 생크림 케이크입니다. 베어리스타 초콜릿 사인판이 올라가 있습니다. (지름 16cm / 중량 675g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/05/%5B9300000004100%5D_20220523144316602.jpg', null::integer, 231::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('세븐 레이어 가나슈 케이크', '케이크', '초콜릿, 가나슈, 모카로 만든 시트와 크림으로 만든 7개의 층이 특징이며, 가나슈로 감싸 진한 풍미의 초콜릿 케이크입니다. (지름 12cm / 중량 510g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/05/%5B9300000002065%5D_20220523145502021.jpg', null::integer, 232::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('청담스타 얼 그레이 밀크 케이크', '케이크', '얼 그레이 케이크 시트 사이에 부드럽고 향긋한 얼 그레이 생크림을 샌드한 케이크입니다. (사이즈 15cm / 중량 520g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/05/%5B9300000001521%5D_20220523145258639.jpg', null::integer, 233::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('티라미수 크레이프 케이크', '케이크', '촉촉한 커피 시트 위에 진한 마스카포네 치즈 크림과 얇게 구워낸 모카 크레이프를 층층이 쌓아올린 티라미수 케이크 입니다. (지름 13.5cm / 중량 330g)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006880%5D_20260818090612678.jpg', null::integer, 234::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('무화과 잠봉 루꼴라 샌드위치', '샌드위치', '겉은 바삭, 속은 쫄깃한 루스틱 브레드에 발사믹이 더해진 달콤상콤한 무화과 리플잼, 부드러운 리코타 치즈와 잠봉, 향긋한 루꼴라가 어우러져 담백하게 즐길 수 있는 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006829%5D_20260928095541112.jpg', null::integer, 235::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('프렌치 어니언 멜팅 치즈 샌드위치', '샌드위치', '프렌치 어니언 스프를 모티브로, 달콤하게 볶은 발사믹 어니언과 햄, 풍성하게 녹아내리는 3가지 치즈가 고대곡물 파로를 넣어 구수함을 더한 사워도우와 어우러져 깊고 진한 가을 풍미를 담은 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006856%5D_20260910143712578.jpg', null::integer, 236::integer, array['soy', 'milk', 'egg', 'wheat', 'shellfish', 'pork', 'chicken', 'beef', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('당근 산도롱 샌드위치', '샌드위치', '당근 식빵 사이에 아삭한 당근 라페와 잠봉 햄, 스크램블 에그를 넣은 샌드위치입니다. * 산도롱은 ''시원한''이라는 뜻의 제주도 방언입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2023/03/%5B9300000004506%5D_20230320090823437.jpg', null::integer, 237::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'shellfish', 'pork', 'beef', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('더블 에그 브렉퍼스트 & 체다 샌드위치', '샌드위치', '쫄깃한 잉글리쉬 머핀 사이에 담백한 에그 프라이 두 장과 포크 패티를 넣고 체다치즈로 감칠맛을 낸 든든한 아침을 위한 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/11/%5B9300000005697%5D_20241120104432369.jpg', null::integer, 238::integer, array['soy', 'milk', 'egg', 'wheat', 'shellfish', 'pork']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('더블 치킨 브레스트 체다 & 에그 샌드위치', '샌드위치', '쫄깃한 잉글리시 머핀 사이 담백한 닭가슴살로 만든 치킨 브레스트 햄과 베이컨, 에그 프라이, 체다 치즈, 스윗 올리브& 칠리 마요 소스로 부드러우면서 매콤한 맛을 더한 모닝 샌드위치 입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/08/%5B9300000005349%5D_20240802095756947.jpg', null::integer, 239::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'shellfish', 'pork', 'chicken']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('멜팅 치즈 베이컨 토스트', '샌드위치', '프렌치토스트 스타일로 구워낸 빵 사이에 에그 스프레드를 샌드하고 빵 위에 치즈와 베이컨을 얹어 구운 토스트입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/01/%5B9300000005813%5D_20250110155406172.jpg', null::integer, 240::integer, array['soy', 'milk', 'egg', 'wheat', 'pork', 'chicken', 'beef']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('모짜렐라 포크 커틀릿 샌드위치', '샌드위치', '폭신한 식빵 안에 겹겹의 포크 커틀릿과 고소한 모짜렐라 치즈, 달콤한 카라멜 어니언 돈카츠 소스와 알싸한 블랙페퍼 아이올리 소스가 어우러진 샌드위치 입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006634%5D_20260827090848261.jpg', null::integer, 241::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'shellfish', 'pork', 'beef', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('미트 칠리 핫도그', '샌드위치', '브리오슈번 사이 육즙 가득한 소시지와 미트 칠리 & 사워크림 소스로 감칠맛을 더하고, 그릴드 베지터블과 치즈로 조화로운 맛을 낸 핫도그입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000006431%5D_20260415083650734.jpg', null::integer, 242::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'shellfish', 'pork', 'chicken', 'beef', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바질 치킨 토마토 브리또', '샌드위치', '향긋한 바질 페스토로 버무린 치킨과 감칠맛을 살린 토마토 라이스에 고소한 모짜렐라 치즈로 풍미를 더해 따뜻하게 구워낸 브리또입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/03/%5B9300000005859%5D_20250311155315768.jpg', null::integer, 243::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'shellfish', 'chicken', 'beef']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바질 치킨 토마토 샌드위치', '샌드위치', '고소한 곡물 식빵 안에 바질 치킨 샐러드와 토마토, 신선한 로메인, 발사믹 어니언이 어우러진 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9300000006549%5D_20260727103107787.jpg', null::integer, 244::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'chicken', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('바질 토마토 탕종 베이글 샌드', '샌드위치', '쫄깃한 올리브 탕종 베이글에 상큼한 반건조 토마토를 넣은 크림치즈와 바질 페스토를 더하여 산뜻한 여름에도 가볍게 즐길 수 있는 베이글 샌드입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/07/%5B9300000005233%5D_20240704143442188.jpg', null::integer, 245::integer, array['soy', 'milk', 'wheat', 'tomato']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베이컨 체다 & 오믈렛 샌드위치', '샌드위치', '고소한 버터 풍미의 브리오슈 감자 번 사이 도톰한 오믈렛과 베이컨, 체다 치즈와 케이준& 마요 소스로 부드러우면서 매콤한 맛을 더한 모닝 샌드위치 입니다', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/08/%5B9300000005350%5D_20240802095851565.jpg', null::integer, 246::integer, array['soy', 'milk', 'egg', 'wheat', 'pork', 'beef']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스크램블 에그 베이컨 샌드위치', '샌드위치', '노릇하게 구운 브리오슈 식빵 사이 따뜻하고 부드러운 스크램블 에그와 고소한 베이컨을 샌드하고 연유 마요로 감칠맛을 더한 토스트 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/09/%5B9300000006121%5D_20250923123535850.jpg', null::integer, 247::integer, array['soy', 'milk', 'egg', 'wheat', 'shellfish', 'pork', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('에그 클럽 샌드위치', '샌드위치', '식빵에 새콤달콤한 그릭 소스를 바르고 고소한 에그 스프레드와 햄, 치즈에 신선함을 더할 로메인을 조합한 클럽 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/12/%5B9300000005698%5D_20251224140934477.jpg', null::integer, 248::integer, array['soy', 'milk', 'egg', 'wheat', 'pork', 'beef']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('치킨 & 머쉬룸 멜팅 치즈 샌드위치', '샌드위치', '부드러우면서 바삭한 바게트 빵 사이에 담백한 닭가슴살과 풍미 깊은 머쉬룸소스를 버무린 버섯 사이로 녹아내린 치즈가 조화로운 바게트 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/04/%5B9300000005157%5D_20240430143823711.jpg', null::integer, 249::integer, array['soy', 'milk', 'egg', 'wheat', 'chicken']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('크랜베리 치킨 샌드위치', '샌드위치', '고소한 호밀 식빵 안에 크랜베리와 호두가 들어간 치킨 샐러드와 신선한 로메인, 토마토가 어우러진 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/05/%5B9300000005855%5D_20250521092733765.jpg', null::integer, 250::integer, array['walnut', 'soy', 'egg', 'wheat', 'tomato', 'chicken', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('크로크무슈', '샌드위치', '고소한 베사멜 소스와 햄, 3가지 치즈(스위스, 에멘탈, 체다)로 깊은 풍미를 완성한 크로크무슈입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9300000006468%5D_20260206095322628.jpg', null::integer, 251::integer, array['soy', 'milk', 'egg', 'wheat', 'pork', 'chicken']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('햄 & 루꼴라 페스토 샌드위치', '샌드위치', '쫄깃한 올리브 치아바타 사이 루꼴라 페스토를 바르고 치즈를 가득 얹은 뒤 치킨 햄과 반건조 토마토, 올리브 마요 소스로 감칠맛을 더해 따뜻하게 구워낸 샌드위치입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000005567%5D_20260420091433479.jpg', null::integer, 252::integer, array['soy', 'milk', 'egg', 'wheat', 'tomato', 'chicken', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카라멜 커스터드 푸딩', '요거트', '신선한 우유와 달걀을 듬뿍 넣어 부드러운 푸딩 속에 달콤한 카라멜 시럽을 더했습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006872%5D_20261007130134170.jpg', null::integer, 253::integer, array['milk', 'egg']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('복숭아 가득 핸디 젤리', '요거트', '국내산 복숭아를 가득 담은 달콤한 맛의 스타벅스 핸디 젤리입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9300000004508%5D_20251022132204611.jpg', null::integer, 254::integer, array['soy', 'peach']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('프리미엄 바나나', '요거트', null::text, 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B5110009171%5D_20210421162111179.jpg', null::integer, 255::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('하루 한 컵 RED+', '요거트', '국내산 사과와 대추 방울 토마토를 한 컵에 담아 언제 어디서나 편하게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/01/%5B9300000005088%5D_20240102110826378.jpg', null::integer, 256::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('한라봉 가득 핸디 젤리', '요거트', '제주도 특산물인 한라봉과 감귤을 가득 담은 상큼한 맛의 스타벅스 핸디 젤리입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/10/%5B9300000001912%5D_20251030083722576.jpg', null::integer, 257::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('한개란', '요거트', '동물복지 인증 농장에서 건강하게 자란 닭이 낳은 무항생제 계란으로 만든 1구 반숙란입니다. (난각번호 2번)', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/09/%5B9300000006068%5D_20250903092534055.jpg', null::integer, 258::integer, array['egg']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('클로버 틴 초콜릿', '초콜릿', '행운을 상징하는 네잎 클로버 초콜릿과 응원의 메시지를 함께 담은 상품입니다. 클로버 틴 케이스와 함께 달콤한 행운을 전하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006881%5D_20261007132126024.jpg', null::integer, 259::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('핑거 초콜릿 파우치 세트', '초콜릿', '크런치, 돌체, 베리 핑거 초콜릿이 각각 2개씩 들어있는 세트 상품입니다. 필통으로 활용할 수 있는 특별한 파우치에 담은 초콜릿으로 달콤한 응원의 마음을 전하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006882%5D_20261007132246014.jpg', null::integer, 260::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('(10개입)인절미찰떡파이', '초콜릿', '쫀득한 찰떡 속에 고소한 인절미 크림을 채운 파이가 10개 들어있는 상품입니다. 땅콩과 초콜릿을 코팅하여 더욱 고소하고 달콤하게 즐기실 수 있습니다. 찰떡파이로 합격의 기운을 선물하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006875%5D_20261007131923227.jpg', null::integer, 261::integer, array['peanut', 'soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('버터 카라멜 샌드 쿠키', '초콜릿', '사이렌 로고 모양의 고소한 버터 쿠키 사이에 달콤한 카라멜 필링을 채운 쿠키입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006877%5D_20260923091736343.jpg', null::integer, 262::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('클로버 샌드 쿠키', '초콜릿', '행운의 상징인 네잎클로버 모양의 버터 카라멜 샌드 쿠키와 다크 카라멜 샌드 쿠키가 각각 8개씩 들어있는 세트 상품입니다. 클로버 샌드 쿠키로 응원하는 마음을 전하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006028%5D_20261007131732834.jpg', null::integer, 263::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('마롱 마들렌', '초콜릿', '국내산 우리 밤을 가득 담아 가을의 맛을 즐길 수 있는 마들렌입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006209%5D_20260928095729253.jpg', null::integer, 264::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('마롱 찰떡 세트', '초콜릿', '가을 제철 밤의 깊은 풍미를 담은 쫀득한 찰떡이 4개 들어있는 상품입니다. 쫀득 마롱 찰떡으로 합격을 기원하는 마음을 전하세요. * 쫀득 마롱 찰떡을 맛있게 즐기는 TIP ㆍ실온 10분 해동 시 아이스크림처럼 시원하고 부드러운 식감으로 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/10/%5B9300000006887%5D_20261007132517627.jpg', null::integer, 265::integer, array['soy', 'milk', 'pork', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('쫀득 마롱 찰떡', '초콜릿', '달콤한 밤을 쫀득한 찰떡에 가득 담은 디저트 입니다. 쫀득한 식감 속 마롱 필링과 크림의 깊은 풍미를 즐길 수 있습니다. * 쫀득 마롱 찰떡을 맛있게 즐기는 TIP ㆍ실온 10분 해동 시 아이스크림처럼 시원하고 부드러운 식감으로 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/09/%5B9300000006883%5D_20260910143912053.jpg', null::integer, 266::integer, array['soy', 'milk', 'pork', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('돌체 핑거 초콜릿', '초콜릿', '바닐라 밀크 필링을 가득 채워 더욱 부드럽습니다. 6등분 되어 개별 포장된 스틱 타입으로 간편하게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/01/%5B9300000005528%5D_20260109152531374.jpg', null::integer, 267::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('돌체 핑거 초콜릿 세트', '초콜릿', '바닐라 밀크 필링을 가득 채워 더욱 부드럽습니다. 돌체 핑거 초콜릿이 3개 들어있는 세트로 가볍게 선물하기 좋은 초콜릿입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/01/%5B9300000005533%5D_20260123124409253.jpg', null::integer, 268::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('러스크 어소트먼트 세트', '초콜릿', '깊은 풍미의 말차, 단짠 매력의 핑크 솔트 화이트, 고소한 호지차 3가지 맛으로 구성한 러스크 세트입니다. 각기 다른 매력의 러스크와 함께 특별한 티타임을 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006834%5D_20260813102434118.jpg', null::integer, 269::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('리저브 초콜릿 세트', '초콜릿', '벨기에와 프랑스산 재료를 넣은 프리미엄 초콜릿으로 리저브 커피와 드시면 더욱 맛이 좋습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000001610%5D_20210430112116995.jpg', null::integer, 270::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베리 핑거 초콜릿', '초콜릿', '건조 딸기가 톡톡 씹히는 딸기 필링이 가득 들어 있습니다. 6등분 되어 개별 포장된 스틱 타입으로 간편하게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/12/%5B9300000005815%5D_20251212134957283.jpg', null::integer, 271::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베리 핑거 초콜릿 세트', '초콜릿', '건조 딸기가 톡톡 씹히는 딸기 필링이 가득 들어 있습니다. 6등분 되어 개별 포장된 스틱 타입으로 간편하게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000005814%5D_20260420162427036.jpg', null::integer, 272::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 리저브 오리진 초콜릿 다크 70', '초콜릿', '탄자니아 카카오빈을 사용해 만든 코코아 매스와 비정제 원당으로 초콜릿 고유의 풍미를 즐길 수 있습니다. 기분 좋은 산미가 특징인 카카오 함량 70%의 탄자니아 카카오의 매력을 느껴보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/04/%5B9300000005546%5D_20250422091758966.jpg', null::integer, 273::integer, array['soy']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 리저브 오리진 초콜릿 밀크', '초콜릿', '에콰도르 카카오빈을 사용해 만든 코코아 매스로 고급스러운 단맛을 즐길 수 있습니다. 고소하고 부드러운 풍미의 조화가 특징인 에콰도르 카카오의 매력을 느껴보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/04/%5B9300000005547%5D_20250422092151793.jpg', null::integer, 274::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('제주 오름 초콜릿 세트', '초콜릿', '[제주지역 한정푸드] 제주의 유명 자연 경관인 오름 모양을 형상화한 초콜릿 세트 입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/03/%5B9300000001257%5D_20260325110501876.jpg', null::integer, 275::integer, array['peanut', 'soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('크런치 핑거 초콜릿', '초콜릿', '달콤한 솔티드 카라멜 초콜릿에 아몬드가 콕콕 박혀있어 오도독 씹는 즐거움을 더합니다. 6등분 되어 개별 포장된 스틱 타입으로 간편하게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000006493%5D_20260403101354468.jpg', null::integer, 276::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('헤이즐넛 볼 초콜릿 밀크', '초콜릿', '통 헤이즐넛을 밀크 초콜릿으로 감싸 고소하고 달콤합니다. 휴대하기 간편한 패키지로 언제 어디서든 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/07/%5B9300000005372%5D_20240709162811414.jpg', null::integer, 277::integer, array['soy', 'milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('(6개입)카다이프찰떡파이', '초콜릿', '쫀득한 찰떡 속에 바삭한 카다이프와 달콤하고 고소한 피스타치오 크림을 채운 파이가 6개 들어있는 상품입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000006499%5D_20260410171041099.jpg', null::integer, 278::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('스타벅스 너티 쿠키', '초콜릿', '헤이즐넛, 아몬드가 들어가서 더욱 고소한 맛의 너티 쿠키입니다. 스타벅스에서만 만나볼 수 있는 쿠키를 스타벅스의 음료와 함께 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9300000005315%5D_20260209082722861.jpg', null::integer, 279::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 너티 쿠키 틴 세트', '초콜릿', '헤이즐넛과 아몬드가 들어가서 더욱 고소한 맛의 너티 쿠키가 8개 들어있는 상품입니다. 선물하기 좋은 틴 케이스에 담긴 고소한 너티 쿠키로 마음을 전하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/01/%5B9300000005313%5D_20260108130817138.jpg', null::integer, 280::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 초코 쿠키 틴 세트', '초콜릿', '코코아의 깊고 진한 풍미가 한입에 퍼지는 바삭한 초코 쿠키가 틴 케이스에 8개 들어있는 상품입니다. 스타벅스에서만 만나볼 수 있는 달콤한 초코 쿠키로 특별함을 더하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/01/%5B9300000005687%5D_20260108125411284.jpg', null::integer, 281::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('스타벅스 치즈 쿠키', '초콜릿', '파마산 치즈의 짭조름한 맛과 버터의 풍미가 조화로운 쿠키입니다. 스타벅스에서만 만나볼 수 있는 고소한 치즈 쿠키를 음료와 함께 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/05/%5B9300000006428%5D_20260514102727632.jpg', null::integer, 282::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('아몬드 정과 세트', '초콜릿', '아몬드를 바삭하게 구워 벌꿀과 황설탕으로 코팅한 달콤한 견과류 간식입니다. 아몬드, 감태, 흑임자 맛 3가지를 다양하게 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000006319%5D_20260428085839301.jpg', null::integer, 283::integer, array['milk']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('우리쌀 전병 땅콩맛', '초콜릿', '우리쌀로 만든 전병 위에 땅콩을 토핑하여 더욱 고소한 상품입니다. 전병 3개가 들어간 봉지가 총 4봉 들어있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006322%5D_20260824090032920.jpg', null::integer, 284::integer, array['soy', 'milk', 'egg']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('우리쌀 전병 파래김맛', '초콜릿', '우리쌀로 만든 전병 위에 파래김을 토핑하여 더욱 감칠맛 나는 상품입니다. 전병 3개가 들어간 봉지가 총 4봉 들어있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006321%5D_20260824085715152.jpg', null::integer, 285::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('초콜릿 칩 쿠키 바스켓', '초콜릿', '달콤한 초콜릿 칩이 콕콕 박힌 부드러운 쿠키입니다. 바스켓에 달린 메시지 택에 마음을 적어 감사한 분에게 선물하세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/05/%5B9300000006162%5D_20260518085529294.jpg', null::integer, 286::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('쿠키 스트로우 단품', '초콜릿', '바삭한 식감이 특징인 웨이퍼롤 타입의 스낵입니다. 바닐라향의 쿠키 속을 달콤한 초콜릿으로 코팅했습니다. 스트로우처럼 음료에 꽂아서 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9300000006019%5D_20260209081845659.jpg', null::integer, 287::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('쿠키 스트로우 세트', '초콜릿', '바삭한 식감이 특징인 웨이퍼롤 타입의 쿠키 스트로우가 19개 들어있는 세트 상품입니다. 바닐라향의 쿠키 속을 달콤한 초콜릿으로 코팅했습니다. 스트로우처럼 음료에 꽂아서 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/02/%5B9900000001722%5D_20260209082226686.jpg', null::integer, 288::integer, array['peanut', 'soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('풀문 잼 쿠키 세트', '초콜릿', '고소한 버터 쿠키 위에 달콤한 과일 잼을 올린 추석 보름달을 닮은 쿠키 세트입니다. 온가족이 나누어먹기 좋은 24입 구성이며, 달콤한 사과잼이 올라간 쿠키와 상큼한 딸기잼이 올라간 쿠키가 각각 12개씩 들어있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006825%5D_20260813102221820.jpg', null::integer, 289::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('피넛초코찰떡파이 6개입', '초콜릿', '쫀득한 찰떡 속에 달콤한 헤이즐넛 크림을 채운 파이가 6개 들어있는 상품입니다. 땅콩과 초콜릿을 코팅하여 더욱 고소하고 달콤하게 즐기실 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/01/%5B9300000006388%5D_20260123123526536.jpg', null::integer, 290::integer, array['peanut', 'soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('다크 초콜릿 마카롱', '초콜릿', '겉은 바삭하고 속은 쫄깃한 초코 가나슈가 샌드된 진한 맛의 초콜릿 마카롱입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000001924%5D_20210421133005814.jpg', null::integer, 291::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('초콜릿 피낭시에', '초콜릿', '달콤한 초콜릿 칩을 듬뿍 올려 깊고 진한 초콜릿 맛을 느낄 수 있는 피낭시에입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B9300000005608%5D_20241028092655837.jpg', null::integer, 292::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('클래식 피낭시에', '초콜릿', '진한 버터 풍미가 느껴지는 겉은 쫀득하고 속은 촉촉한 식감의 피낭시에입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/10/%5B9300000005609%5D_20241028092618551.jpg', null::integer, 293::integer, array['milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('하트 스트로베리 마카롱', '초콜릿', '하트 모양의 겉은 바삭하고 속은 쫄깃한 상큼한 딸기 맛 마카롱입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/01/%5B9300000004517%5D_20250116140423596.jpg', null::integer, 294::integer, array['milk', 'egg', 'wheat', 'sulfites']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('(14개입)오도독 하루 넛&블루베리', '초콜릿', '고소한 4가지의 프리미엄 견과류와 달콤한 블루베리를 담은 한 입 간식입니다. 선물하기 좋은 박스에 14개를 담은 구성으로, 소중한 분에게 마음을 전해보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9900000001980%5D_20260813102958523.jpg', null::integer, 295::integer, array['walnut']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('그래놀라 칩', '초콜릿', '우리 당근 말랭이와 시금치를 현미, 아몬드와 함께 넣어 바삭하게 구운 칩입니다. 한 입에 먹기 좋은 그래놀라 칩을 음료와 함께 즐겨보세요.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/05/%5B9300000006410%5D_20260514103006436.jpg', null::integer, 296::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('말랑쫀득 고구마바', '초콜릿', '전북 고창 고구마로 만든 말랑하고 쫀득한 한 입 간식입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006824%5D_20260813103508000.jpg', null::integer, 297::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('바질 토마토 베이글칩', '초콜릿', '향긋한 바질 토마토 올리브 베이글에 진한 로제 시즈닝을 더한 베이글칩입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/12/%5B9300000005560%5D_20241213093127727.jpg', null::integer, 298::integer, array['soy', 'milk', 'wheat', 'tomato']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('버터바', '초콜릿', '입안을 가득 채우는 풍성한 버터 풍미가 느껴지는 스틱 형태의 디저트 버터바입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2023/06/%5B9300000004784%5D_20230613153946645.jpg', null::integer, 299::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('베이스볼 팝콘&프레첼', '초콜릿', '야구공 모양의 달콤 짭짤한 버터 팝콘과 고소한 프레첼을 대용량 사이즈로 담아 야구 관람 시 함께 즐기기 좋은 스낵입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/04/%5B9300000006466%5D_20260415083814229.jpg', null::integer, 300::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('별별꾸러미', '초콜릿', '6가지 스낵을 꾸러미백과 구성하여 다양하게 즐길 수 있는 상품입니다. ※ 상품구성 : 꾸러미백, 바질 토마토 베이글칩, 한 입에 쏙 설향 딸기칩, 카라멜 팝콘&프레첼, 오리지널 템페칩, 그래놀라 칩, 크런치 핑거 초콜릿', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9900000001764%5D_20260713125111525.jpg', null::integer, 301::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('오도독 하루 넛&블루베리', '초콜릿', '고소한 4가지의 프리미엄 견과류와 달콤한 블루베리를 담은 한 입 간식입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/08/%5B9300000006823%5D_20260813102816704.jpg', null::integer, 302::integer, array['walnut']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('오리지널 템페칩', '초콜릿', '콩을 발효시켜 만든 템페를 얇게 썰어 바삭하게 즐기는 담백하고 짭짤한 스낵입니다. ※ 템페란 콩을 발효시켜 만든 인도네시아 전통 음식으로, 단백질과 칼슘, 식이섬유 등의 영양소가 들어있는 식재료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/01/%5B9300000005563%5D_20250103103655211.jpg', null::integer, 303::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('자일리톨 캔디 크리스탈 레몬', '초콜릿', '자작나무에서 추출한 핀란드산 천연 자일리톨로 만든 크리스탈 원석 형태의 무설탕 캔디입니다. (자일리톨 98.5%, 레몬향 첨가) 미니 틴케이스에 담아 편리하게 드실 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2021/04/%5B9300000002556%5D_20210422111709262.jpg', null::integer, 304::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('초콜릿 바닐라 그래놀라', '초콜릿', '발리 여행에서 꼭 사오는 간식! YAVA 초콜릿 바닐라 그래놀라를 소개합니다. 야자나무 설탕과 캐슈넛이 어우러진 고소한 통곡물 그래놀라입니다. ※ 파예 무지방 요거트와 함께 하면 더욱 맛있게 즐길 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/11/%5B9300000006125%5D_20251111085902666.jpg', null::integer, 305::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('치즈 감자 베이글칩', '초콜릿', '고소한 감자 베이글에 짭조름한 파마산 치즈 시즈닝을 더한 베이글칩입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2026/07/%5B9300000006765%5D_20260715100949613.jpg', null::integer, 306::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('카라멜 팝콘&프레첼', '초콜릿', '달콤 바삭한 카라멜 팝콘과 고소 짭짤한 프레첼이 어우러진 단짠단짠 매력의 스낵입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/07/%5B9300000006083%5D_20250722164229101.jpg', null::integer, 307::integer, array['soy', 'milk', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('한 입에 쏙 고구마', '초콜릿', '전북 고창 고구마로 건조한 고구마 말랭이입니다. 큐브 형태로 한 입에 간편하게 즐기실 수 있습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/12/%5B9300000005562%5D_20241213093414584.jpg', null::integer, 308::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('한 입에 쏙 설향 딸기칩', '초콜릿', '국산 설향 딸기를 동결 건조하여 새콤달콤한 맛을 그대로 담은 과일 스낵입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2024/12/%5B9300000005559%5D_20241213093029273.jpg', null::integer, 309::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('한 입에 쏙 카스텔라', '초콜릿', '국내산 달걀을 넣어 구운 카스텔라를 한 입 크기로 잘라 다시 한번 구워낸 바삭한 카스텔라 러스크입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2022/10/%5B9300000002718%5D_20221020095146597.jpg', null::integer, 310::integer, array['soy', 'milk', 'egg', 'wheat']::text[], array[]::text[], array[]::text[], 'Starbucks Korea menu (starbucks.co.kr)', null::text, array[]::text[]),
  ('한입에 쏙 공주 알밤', '초콜릿', '국내산 공주 밤을 껍질 제거 후 그대로 쪄낸 간식입니다. 국내 최대 산지인 공주 밤을 엄선해 알이 크고 단 맛이 좋습니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/03/%5B9300000002000%5D_20250318092005568.jpg', null::integer, 311::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('핫칠리 템페칩', '초콜릿', '콩을 발효시켜 만든 템페를 얇게 썰어 바삭하게 즐기는 매콤하고 짭짤한 스낵입니다. ※ 템페란 콩을 발효시켜 만든 인도네시아 전통 음식으로, 단백질과 칼슘, 식이섬유 등의 영양소가 들어있는 식재료입니다.', 'https://image.istarbucks.co.kr/upload/store/skuimg/2025/01/%5B9300000005565%5D_20250103103759122.jpg', null::integer, 312::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[])
) as v;

with r as (
  insert into public.restaurants (name, cuisine, logo, logo_bg, delivery_link)
  values ('Subway', 'Sandwiches', 'https://www.subway.co.kr/images/common/logo_w.png', '#ffffff', 'https://www.subway.co.kr')
  returning id
)
insert into public.menu_items (restaurant_id, name, category, description, photo, price, sort_order, contains, may_contain, ingredients, allergen_source, allergen_note, allergen_gaps)
select r.id, v.* from r, (values
  ('램 & 후무스 Lamb & Hummus', '샌드위치', '부드러운 양고기와 후무스로 풍미와 식감을 즐길 수 있는 메뉴', 'https://www.subway.co.kr/upload/menu/1791792537590_jNhWrL.png', null::integer, 0::integer, array['milk', 'soy', 'wheat', 'tomato', 'sulfites', 'beef']::text[], array['egg', 'buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'pork', 'peach', 'walnut', 'chicken', 'squid', 'shellfish', 'pine_nut']::text[], array['파마산 오레가노', '아메리칸 치즈', '램', '후무스', '야채 4종', '치미추리 소스', '홀스래디쉬']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
  ('램 Lamb', '샌드위치', '육즙 가득 양고기에 허브향을 더해 입안 가득 이국적인 풍미를 즐길 수 있는 메뉴', 'https://www.subway.co.kr/upload/menu/1791792321367_fCUKeS.png', null::integer, 1::integer, array['milk', 'soy', 'wheat', 'tomato', 'beef']::text[], array['egg', 'buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'pork', 'peach', 'sulfites', 'walnut', 'chicken', 'squid', 'shellfish', 'pine_nut']::text[], array['파마산 오레가노', '아메리칸 치즈', '램', '야채 4종', '치미추리 소스', '홀스래디쉬']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
  ('피자썹 Pizza Sub', '샌드위치', '토마토살사에 모차렐라치즈가 듬뿍, 간편하고 맛있게 즐기는 피자썹 (고정레시피 제품입니다)', 'https://www.subway.co.kr/upload/menu/1781152604561_TA6XRx.png', null::integer, 2::integer, array['egg', 'milk', 'soy', 'wheat', 'pork', 'tomato']::text[], array['buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'peach', 'sulfites', 'walnut', 'chicken', 'beef', 'squid', 'shellfish', 'pine_nut']::text[], array[]::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
  ('안창 비프&머쉬룸 Beef & Mushroom', '샌드위치', '부드럽고 풍미 넘치는 안창살과 담백하고 건강한 머쉬룸이 함께 어우러져 이루는 맛있는 조합의 샌드위치', 'https://www.subway.co.kr/upload/menu/%EC%95%88%EC%B0%BD-%EB%B9%84%ED%94%84&%EB%A8%B8%EC%89%AC%EB%A3%B8_20240912031749239.png', null::integer, 3::integer, array['soy', 'wheat', 'tomato', 'beef']::text[], array['egg', 'milk', 'buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'pork', 'peach', 'sulfites', 'walnut', 'chicken', 'squid', 'shellfish', 'pine_nut']::text[], array['위트', '안창 비프', '머쉬룸', '모짜렐라 치즈', '야채 5종', '스위트 어니언', '랜치']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
  ('스테이크 & 치즈 Steak & Cheese', '샌드위치', '육즙이 쫙~풍부한 비프 스테이크의 풍미가 입안 한가득', 'https://www.subway.co.kr/upload/menu/Steak-&-Cheese_20211231095455613.png', null::integer, 4::integer, array['milk', 'soy', 'wheat', 'tomato', 'beef']::text[], array['egg']::text[], array['화이트', '스테이크 1스쿱', '아메리칸 치즈', '야채 5종', '올리브', '피클', '할라피뇨', '마요네즈', '사우스웨스트 치폴레']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
  ('이탈리안 비엠티 Italian B.M.T.™', '샌드위치', '페퍼로니, 살라미 그리고 햄이 만들어내는 최상의 조화 전세계가 사랑하는 써브웨이의 베스트셀러 Biggest Meatiest Tastiest, its’ B.M.T.', 'https://www.subway.co.kr/upload/menu/Italian_B.M.T_20211231094910899.png', null::integer, 5::integer, array['soy', 'wheat', 'pork', 'tomato']::text[], array['egg', 'milk', 'buckwheat', 'peanut', 'mackerel', 'crab', 'shrimp', 'peach', 'sulfites', 'walnut', 'chicken', 'beef', 'squid', 'shellfish', 'pine_nut']::text[], array['파마산 오레가노', '페퍼로니 3장', '살라미 3장', '햄 2장', '슈레드 치즈', '야채 5종', '올리브', '피클', '할라피뇨', '스위트 어니언', '랜치']::text[], 'Subway Korea allergy chart (subway.co.kr/sandwichAllergy)', 'Chart covers the base dish. Your bread, cheese and sauce can add more.', array[]::text[]),
