select r.id, v.* from r, (values
  ('아그작딥라떼', '커피', '아그작딥라떼 --> 깊은 풍미의 라떼 베이스에 데메라라 슈가의 아그작 씹는 재미를 더한 아그작딥라떼 ※ 디카페인 옵션 선택을 통해 주문이 가능합니다. *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 아이스(ICED) 기준 *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_L3oagAQI_20261013212802.png', null::integer, 0::integer, array['milk']::text[], array[]::text[], array[]::text[], 'The Venti menu (theventi.co.kr)', null::text, array[]::text[]),
  ('시그니처딥라떼 (라지/점보)', '커피', '시그니처딥라떼 (라지/점보) --> 깊고 더 고소한 더벤티만의 시그니처 베이스로 완성한 카페 라떼 ※ 디카페인 옵션 선택을 통해 주문이 가능합니다. *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 아이스(ICED) 기준 *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 **HOT 음료나 점보 사이즈(960ml) 영양성분은 공지사항 내 게시물 확인 부탁드립니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_Px1DHNOd_20260612154418.png', null::integer, 1::integer, array['milk']::text[], array[]::text[], array[]::text[], 'The Venti menu (theventi.co.kr)', null::text, array[]::text[]),
  ('레샷추', '커피', '레샷추 --> 달콤한 꿀과 상큼한 레몬에 더벤티의 진한 에스프레소가 어우러진 레샷추 *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 아이스(ICED) 기준 **점보 사이즈(960ml) 영양성분은 공지사항 내 게시물 확인 부탁드립니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_fPejNO5U_20260612154251.png', null::integer, 2::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아샷추', '커피', '아샷추 --> 진한 홍차와 달콤한 복숭아에 더벤티의 진한 에스프레소가 어우러진 아샷추 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 아이스(ICED) 기준 *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 **점보 사이즈(960ml) 영양성분은 공지사항 내 게시물 확인 부탁드립니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_jRsvGfIk_20260612155533.png', null::integer, 3::integer, array['peach']::text[], array[]::text[], array[]::text[], 'The Venti menu (theventi.co.kr)', null::text, array[]::text[]),
  ('오트초코카페라떼', '커피', '오트초코카페라떼 --> 오트 베이스에 단백질 초코와 에스프레소를 더해 밸런스 있게 즐길 수 있는 오트초코카페라떼 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 기준 *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 ※ 어린이, 임산부, 카페인 민감자의 경우 고카페인 음료 섭취에 주의하시기 바랍니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_j2PYxCva_20260612155656.png', null::integer, 4::integer, array['milk', 'soy']::text[], array[]::text[], array[]::text[], 'The Venti menu (theventi.co.kr)', null::text, array[]::text[]),
  ('핫 아메리카노 (라지)', '커피', '핫 아메리카노 (라지) --> 더벤티의 깊고 진한 커피 풍미를 느낄 수 있는 핫 아메리카노 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 기준 *원두별 카페인 함량: 시그니처 168mg / 다크 266mg (라지 사이즈 2샷 기준) *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 ※ 어린이, 임산부, 카페인 민감자의 경우 고카페인 음료 섭취에 주의하시기 바랍니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_t1MsToyR_20260612154232.png', null::integer, 5::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('아이스 아메리카노 (라지/점보)', '커피', '아이스 아메리카노 (라지/점보) --> 더벤티의 깊고 진한 커피 풍미를 느낄 수 있는 아이스 아메리카노 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 기준 *원두별 카페인 함량: 시그니처 168mg / 다크 266mg (라지 사이즈 2샷 기준) *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 ※ 어린이, 임산부, 카페인 민감자의 경우 고카페인 음료 섭취에 주의하시기 바랍니다. **점보 사이즈(960ml) 영양성분은 공지사항 내 게시물 확인 부탁드립니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_oc3VbpqI_20260612155546.png', null::integer, 6::integer, null::text[], null::text[], array[]::text[], null::text, null::text, array[]::text[]),
  ('카페라떼 (라지/점보)', '커피', '카페라떼 (라지/점보) --> 더벤티의 진한 에스프레소에 부드러운 우유가 어우러진 고소한 카페라떼 *영양성분 및 성분별 기준치 : 라지(600ml) 사이즈 기준 *원두별 카페인 함량: 시그니처 168mg / 다크 266mg (라지 사이즈 2샷 기준) *고카페인 기준 : 1ml당 0.15mg 이상 카페인 함유 시 ※ 어린이, 임산부, 카페인 민감자의 경우 고카페인 음료 섭취에 주의하시기 바랍니다. **HOT 음료나 점보 사이즈(960ml) 영양성분은 공지사항 내 게시물 확인 부탁드립니다.', 'https://www.theventi.co.kr/new/upload/menu_new/2039262055_0T7iGUDW_20260612155751.png', null::integer, 7::integer, array['milk']::text[], array[]::text[], array[]::text[], 'The Venti menu (theventi.co.kr)', null::text, array[]::text[]),
